window.CLEAR_CODE.register("clear/model/causalflownet.py",{"text":"\"\"\"causalflownet: causal_velocity_field, target_flow.\n\ncausal_velocity_field: Causal velocity field (Stage B): tau-ordered attention -\u003e path velocity.\n\nOnce the priority head has committed an ordering, object i may read only\nobjects that move at-or-before its own turn; the embodiment token, scene\ntokens and immovable objects are static context readable by everyone. The\nhead regresses velocity in each object's OWN path time, so the regression\ntarget is schedule-independent (vanilla conditional flow matching).\n\nThe mask rule that matters (learned the hard way, kept as a gradient test):\ncontext tokens may NOT read movable objects. If they could, a later object's\npose would reach an earlier object through a 2-hop path -- late object -\u003e\ncontext token at layer L -\u003e early object at layer L+1.\n\nein notation:\n  b - batch\n  n - objects\n  t - tokens (1 capability + n objects + s scene)\n\ntarget_flow: CLEAR's task-independent selected-object, order-conditioned target flow.\n\nFlow time is generative time, not controller execution time. Static observations\nare available at every rank; later generated targets are not. Domain adapters\nprovide object/context tokens and interpret/project the final configuration code.\n\"\"\"\n\n# ---- causal_velocity_field ----\nimport torch\nfrom torch import nn\nfrom torch.nn import Module\n\nfrom clear.model.affordancenet import AffordanceTransformer\nfrom clear.model.encoders import CapabilityEncoder\nfrom clear.model.encoders import SCENE_CHANS, SceneEncoder, obj_feat_dim\nfrom clear.util import wall_oob_penalty\n\nfrom clear.model.affordancenet import StageBAuxHeads\n\n# causal mask\n\n\ndef causal_mask(rank, movable, n_scene, causal = True):\n    \"\"\"(b, t, t) bool, True = blocked.\n\n    A movable object key may be read ONLY by a movable object query with an\n    equal-or-later rank. Every other token may read anything EXCEPT movable\n    objects (the 2-hop rule above).\n\n    causal=False = OBSERVATION-CONSISTENT attention (2026-08-26, adopted after\n    experiments/ordering_ablation: abstract plan success 0.30 -\u003e 0.86 at k=3,\n    physical nocausal_s0 0.920 vs 0.884, PLAN sect95/97): every movable object\n    reads every movable object regardless of rank. This is not a leak of future\n    information: under the slot schedule (util.schedule.oracle_progress) a\n    later-ranked object sits at its current pose x0 while an earlier one moves,\n    i.e. exactly what the robot observes at that moment; earlier-ranked objects\n    are read at their parked pose, which is what the robot will observe once they\n    have been executed. clear.PAMO.forward asserts that invariant\n    (_assert_observation_consistent). The context rule (cap/scene/immovable\n    tokens never read movable objects) is kept as is. causal=True is the legacy\n    rank-causal mask, kept for the ablation and for older checkpoints.\n    \"\"\"\n    b, n = rank.shape\n    t = 1 + n + n_scene\n    mask = torch.zeros(b, t, t, dtype = torch.bool, device = rank.device)\n\n    key_is_movable = torch.zeros(b, t, dtype = torch.bool, device = rank.device)\n    key_is_movable[:, 1:1 + n] = movable\n    mask |= key_is_movable[:, None, :]\n\n    allowed = movable[:, :, None] \u0026 movable[:, None, :]\n    if causal:\n        key_is_later = rank[:, None, :] \u003e rank[:, :, None]\n        allowed = allowed \u0026 ~key_is_later\n    mask[:, 1:1 + n, 1:1 + n] \u0026= ~allowed\n    return mask\n\n\ndef causal_bias(rank, movable, n_scene, slope):\n    \"\"\"(b, t, t) float, additive attention-logit penalty for the SOFT causal\n    variant (2026-09-12): rather than hard-blocking a later-ranked movable\n    key (causal=True) or leaving it fully open (causal=False, the existing\n    no_causal_mask ablation, checked in RESULTS.md and NOT found necessary --\n    held-out CI [-1.83, +4.92]), grade the penalty by how much later it is.\n    slope=0 reduces to causal=False exactly; used with causal=False so the\n    2-hop context rule (context tokens never read movable objects) stays the\n    one hard invariant causal_mask always enforces. Caller passes the SAME\n    `rank`/`movable` (selected) tensors given to causal_mask(..., causal=False).\n    \"\"\"\n    b, n = rank.shape\n    t = 1 + n + n_scene\n    bias = rank.new_zeros(b, t, t, dtype = torch.float32)\n    allowed = movable[:, :, None] \u0026 movable[:, None, :]\n    rank_gap = (rank[:, None, :] - rank[:, :, None]).clamp(min = 0).to(torch.float32)\n    bias[:, 1:1 + n, 1:1 + n] = torch.where(allowed, -slope * rank_gap, torch.zeros_like(rank_gap))\n    return bias\n\n# causal velocity field\n\n\nclass CausalVelocityField(StageBAuxHeads, Module):\n    def __init__(self, grid_hw = (8, 8), dim = 128, depth = 4, heads = 4, dim_head = 32,\n                 drop_obj = (), obj_extra_dim = 0, predict_robot_path = False,\n                 condition_smoothness = False, include_reachable = False,\n                 predict_feasibility = False, predict_affordance = False, causal = True,\n                 capability_encoder = None,\n                 scene_channels = SCENE_CHANS):\n        super().__init__()\n        self.causal = causal  # False = no_causal_mask ablation, see causal_mask()\n        self.to_object_tokens = nn.Linear(obj_feat_dim(drop_obj, include_reachable) + obj_extra_dim, dim)\n        # capability_encoder: optional module replacing the default vector\n        # encoder (e.g. kappa_set_encoder.KappaSetEncoder); must map its own\n        # `capability` input to a (b, 1, dim) token.\n        self.capability_encoder = capability_encoder if capability_encoder is not None else CapabilityEncoder(dim)\n        self.scene_encoder = SceneEncoder(dim, grid_hw, channels = scene_channels)\n        # OPT-IN, same contract as predict_robot_path below: condition_smoothness=False\n        # (the default) leaves this class byte-for-byte the old CausalVelocityField --\n        # no extra params, forward()'s signature accepts `smoothness` but ignores it.\n        # When on, a scalar in [0, 1] biases the capability token via a small additive\n        # projection (not a new token -- inserting one would shift every index the\n        # causal mask and the `tokens[:, 1:1+n]` slicing below already hardcode).\n        # `clear/data/data.py`'s `collate(..., smoothness=True)` supplies the matching\n        # TRAINING label: pose/v_target blended toward a Chaikin-smoothed path by the\n        # same scalar, so the network learns what \"more smoothness\" should look like\n        # rather than only being told to reproduce it post-hoc (see\n        # PAMO.sample_robot_path's own, unrelated, post-hoc EMA `smoothness` param --\n        # deliberately named `smoothness_cond` everywhere in this class to not collide).\n        self.condition_smoothness = condition_smoothness\n        if condition_smoothness:\n            self.smoothness_to_bias = nn.Linear(1, dim)\n        self.transformer = AffordanceTransformer(dim, depth = depth, heads = heads, dim_head = dim_head)\n        self.to_velocity = nn.Sequential(\n            nn.Linear(dim, dim),\n            nn.GELU(),\n            nn.Linear(dim, 3),\n        )\n        # Second head off the same trunk: where does this object END UP,\n        # globally (x1 - current pose) -- not just its local path velocity.\n        # flow_loss alone only ever sees the next instant; this is the signal\n        # that lets training penalize an invalid *resulting* world (see\n        # util/validity.py), which the velocity head has no way to express.\n        self.to_endpoint = nn.Sequential(\n            nn.Linear(dim, dim),\n            nn.GELU(),\n            nn.Linear(dim, 3),\n        )\n\n        # Third pair of heads, OPT-IN (predict_robot_path=False leaves this\n        # class byte-for-byte the old CausalVelocityField -- both existing\n        # call sites in clear.py unpack exactly 2 return values and must not\n        # break). Reads the SAME per-object transformer output as\n        # to_velocity/to_endpoint -- no new token, no rank/mask change, so\n        # none of the causal-mask correctness work above is touched. The\n        # physical quantity is different (the ROBOT's own path to reach this\n        # object, not the object's own placement) but the object's token\n        # already carries everything the mask says it may see (earlier-turn\n        # objects' outcomes, capability, scene) -- see module docstring in\n        # clear/data/waypoint_data.py for what supplies the training label\n        # (Roadmap.path_points, not this repo's grid cell_path -- that labels\n        # OBJECT motion, this labels ROBOT motion, a different quantity that\n        # happens to reuse the same pose/velocity CFM parameterisation).\n        #\n        # Robot position between phases is approximated as the causally\n        # PREVIOUS object's own endpoint (where the robot just finished\n        # pushing it to) -- or the scene's start pose for the first-ranked\n        # object. This needs no new input signal (rank + x1 already exist in\n        # the sequence); it is an approximation, not measured, and is the\n        # first thing to revisit if predicted robot paths look wrong at a\n        # phase boundary. See experiments/e4/HANDOFF_sumo_executor.md\n        # \"\uc2a4\ubb3c\uc77c\uacf1 \ubc88\uc9f8 \ud6c4\uc18d\".\n        self.predict_robot_path = predict_robot_path\n        if predict_robot_path:\n            self.to_robot_velocity = nn.Sequential(nn.Linear(dim, dim), nn.GELU(), nn.Linear(dim, 3))\n            self.to_robot_endpoint = nn.Sequential(nn.Linear(dim, dim), nn.GELU(), nn.Linear(dim, 3))\n\n        # Fourth head, OPT-IN (predict_feasibility=False leaves this class\n        # byte-for-byte the old CausalVelocityField, same contract as\n        # predict_robot_path/condition_smoothness above -- forward()'s\n        # existing 2-value return is untouched, only forward_with_feasibility\n        # below uses this). 2026-08-23, PLAN doc S54-62 / experiments/\n        # stageb_clearance_signal/RESULTS.md sect9-10: an RL reward built\n        # from the SAME validated signal (order_index/push_distance/n_movers/\n        # wall-occupancy, sect4-6's v4/v5 feature set) made real placement\n        # accuracy WORSE, not better (miss rate 17.2% -\u003e 41.6%, sect9) --\n        # consistent overoptimization of an imperfect frozen critic via\n        # noisy policy gradient. This head instead trains the SAME kind of\n        # signal via ordinary supervised backprop, directly into the shared\n        # trunk, alongside flow_loss/endpoint_loss -- no policy-gradient\n        # variance, no frozen numpy critic to game. Takes the trunk's own\n        # per-object hidden state PLUS 4 scalars the trunk alone cannot see\n        # (they depend on the CANDIDATE endpoint this same forward pass just\n        # produced, not just the pre-placement context the trunk attends\n        # over): push_distance (from endpoint_delta, literally free --\n        # already computed for endpoint_loss), wall_occ (reuses\n        # wall_oob_penalty's own differentiable bilinear sample, not a new\n        # geometry channel), order_index/n_movers (from `rank`/`movable`,\n        # already in every batch -- v4/v5's single strongest and third-\n        # strongest univariate features, sect6, never before given to any\n        # head as an explicit input). Outputs a per-object SUCCESS LOGIT,\n        # trained with BCEWithLogitsLoss against real physical phase-level\n        # outcomes (the same ~3-4k-row corpus feasibility_critic.py already\n        # builds) -- see clear.py's feasibility_forward for the loss, only\n        # meaningful on batches carrying real labels (see\n        # data/real_corpus.py's build_feasibility_batches).\n        self.predict_feasibility = predict_feasibility\n        if predict_feasibility:\n            self.to_feasibility = nn.Sequential(nn.Linear(dim + 4, dim), nn.GELU(), nn.Linear(dim, 1))\n            # Residual refinement head (2026-08-23, PLAN doc S54-62 sect16 --\n            # experiments/stageb_clearance_signal/RESULTS.md): the actual\n            # CE-Adapter/CrossTracer mechanism (T_e = T_init + Delta_e), which\n            # sect10's feasibility head alone did NOT implement -- confirmed\n            # directly by reading PAMO.sample()'s own ODE loop: it integrates\n            # `velocity` only and DISCARDS endpoint_delta entirely (`_` in\n            # `velocity, _ = self.velocity_field(...)`), so nothing built in\n            # sect10 could ever have reached actual sampled behavior except\n            # indirectly, through gradient shared with the trunk that also\n            # produces `velocity` -- a real, but diffuse and unconstrained,\n            # coupling, consistent with sect12/15's small, seed-noisy effect.\n            # Same `feas_in` input as to_feasibility (same 4 context scalars\n            # + trunk state); output is a BOUNDED xy correction (delta_max,\n            # tanh-squashed -- CrossTracer's own bounding, and this\n            # project's own S54-62 audit (sect8) already found an unbounded\n            # correction path is exactly how a reward gets gamed).\n            self.delta_max = 1.5  # grid cells -- generously covers sect6's push_distance\n            # dose-response finding (the \"sweet spot\" sat around 2 cells, the cliff past ~4;\n            # 1.5 lets the residual meaningfully relocate a placement without being able to\n            # single-handedly walk it out to the danger zone sect6 found)\n            self.to_residual = nn.Sequential(nn.Linear(dim + 4, dim), nn.GELU(), nn.Linear(dim, 2))\n\n        # Fifth head pair, OPT-IN (predict_affordance=False leaves this class\n        # byte-for-byte the old one, same contract as every flag above).\n        # 2026-08-24, RESULTS.md sect22-23: embodiment-conditioned AFFORDANCE\n        # MAP -- per-object (h, w) logits over park cells, supervised by\n        # clear/data/affordance.py's dense oracle labels (oracle.park_valid,\n        # 12 maps/scene, unlimited volume -- the label starvation that sank\n        # sect10-22's per-object-scalar heads does not apply). Standalone\n        # Phase-1 net already cleared the pre-stated gates (held-out per-cell\n        # AUC 0.988, every embodiment \u003e= 0.984 -- train_affordance.py); this\n        # head asks whether the SAME signal can flow through PAMO's own\n        # trunk. Mechanism: object token (query) x scene token (key) dot\n        # product -\u003e coarse (4,4) map in the scene encoder's own token\n        # layout, bilinearly upsampled and refined by a small conv decoder\n        # that re-reads the raw class grid (full-res wall structure the 16\n        # coarse tokens can't carry). The causal mask already lets every\n        # object token read every scene token, and scene tokens never read\n        # movable objects -- so the affordance query is object-conditioned\n        # while the keys stay object-independent, and NOTHING about the mask\n        # changes.\n        self.predict_affordance = predict_affordance\n        if predict_affordance:\n            self.to_afford_q = nn.Linear(dim, dim)\n            self.to_afford_k = nn.Linear(dim, dim)\n            self.afford_decoder = nn.Sequential(\n                nn.Conv2d(1 + 5, dim // 2, 3, padding = 1), nn.GELU(),\n                nn.Conv2d(dim // 2, dim // 2, 3, padding = 1), nn.GELU(),\n                nn.Conv2d(dim // 2, 1, 1),\n            )\n\n    def forward(self, grid, object_features, capability, rank, movable, context = None,\n                smoothness_cond = None):\n        \"\"\"-\u003e (velocity, endpoint_delta), each (b, n, 3). velocity is in each\n        object's own path time; endpoint_delta estimates x1 - pose (used only\n        as an auxiliary training signal -- sample() ignores it, the rollout\n        is still pure CFM integration).\n\n        `context`: see PriorityHead.forward. The mask reads the scene-token\n        count off the tensor rather than off self.scene_encoder, so a front end\n        with a different token count cannot silently mis-mask.\n\n        `smoothness_cond`: (b,) in [0, 1], only read when condition_smoothness=True\n        (required then -- see __init__).\n        \"\"\"\n        out = self._trunk_out(grid, object_features, capability, rank, movable, context, smoothness_cond)\n        return self.to_velocity(out), self.to_endpoint(out)\n\n    def _trunk_out(self, grid, object_features, capability, rank, movable, context = None,\n                   smoothness_cond = None):\n        full, n = self._trunk_full(grid, object_features, capability, rank, movable, context,\n                                   smoothness_cond)\n        return full[:, 1:1 + n]\n\n    def _trunk_full(self, grid, object_features, capability, rank, movable, context = None,\n                    smoothness_cond = None):\n        \"\"\"-\u003e (all transformer token outputs (b, 1+n+s, d), n). _trunk_out is\n        the [1:1+n] object slice of this -- one shared implementation so the\n        affordance head's scene-token reads can never drift from what the\n        object heads were computed with.\"\"\"\n        objects = self.to_object_tokens(object_features)\n        cap_token, scene_tokens = context if context is not None else (\n            self.capability_encoder(capability), self.scene_encoder(grid))\n        if self.condition_smoothness:\n            assert smoothness_cond is not None, \"condition_smoothness=True requires smoothness_cond\"\n            cap_token = cap_token + self.smoothness_to_bias(smoothness_cond.view(-1, 1))[:, None, :]\n        tokens = torch.cat([cap_token, objects, scene_tokens], dim = 1)\n\n        mask = causal_mask(rank, movable, scene_tokens.shape[1], causal = self.causal)\n        return self.transformer(tokens, mask = mask), objects.shape[1]\n\n    # forward_with_{robot_path,feasibility,affordance} live in stageb_aux_heads.py (mixin)\n\n\ndef _self_check():\n    import torch\n\n    from clear.data.capability import FEATURE_DIM\n    from clear.model.encoders import obj_feat_dim\n\n    torch.manual_seed(0)\n    b, n, dim = 2, 4, 32\n    grid = torch.zeros(b, 5, 8, 8)\n    object_features = torch.randn(b, n, obj_feat_dim(()))\n    capability = torch.randn(b, FEATURE_DIM)\n    rank = torch.stack([torch.randperm(n) for _ in range(b)])\n    movable = torch.ones(b, n, dtype = torch.bool)\n\n    # predict_robot_path=False (the default, and what PAMO/MazePAMO's existing\n    # 2 call sites unpack) must be byte-for-byte the pre-extension class.\n    plain = CausalVelocityField(grid_hw = (8, 8), dim = dim, depth = 2, heads = 2, dim_head = 16)\n    assert not hasattr(plain, \"to_robot_velocity\"), \"default field must not carry robot heads at all\"\n    v, e = plain.forward(grid, object_features, capability, rank, movable)\n    assert v.shape == (b, n, 3) and e.shape == (b, n, 3)\n    print(\"ok predict_robot_path=False: no robot heads, forward() shape unchanged\")\n\n    reachable_feats = torch.randn(b, n, obj_feat_dim((), include_reachable = True))\n    with_reachable = CausalVelocityField(grid_hw = (8, 8), dim = dim, depth = 2, heads = 2,\n                                         dim_head = 16, include_reachable = True)\n    v, e = with_reachable.forward(grid, reachable_feats, capability, rank, movable)\n    assert v.shape == (b, n, 3) and e.shape == (b, n, 3)\n    print(\"ok include_reachable=True: to_object_tokens sized for the extra column\")\n\n    vf = CausalVelocityField(grid_hw = (8, 8), dim = dim, depth = 2, heads = 2, dim_head = 16,\n                             predict_robot_path = True)\n    v2, e2, rv, re = vf.forward_with_robot_path(grid, object_features, capability, rank, movable)\n    assert rv.shape == (b, n, 3) and re.shape == (b, n, 3)\n    assert torch.isfinite(rv).all() and torch.isfinite(re).all()\n    v3, e3 = vf.forward(grid, object_features, capability, rank, movable)\n    assert torch.allclose(v2, v3) and torch.allclose(e2, e3), (\n        \"forward() and forward_with_robot_path() must share the identical trunk output\")\n    print(\"ok predict_robot_path=True: robot heads present, shared trunk output matches forward()\")\n\n    (rv.sum() + re.sum()).backward()\n    print(\"ok gradients reach the robot-path heads\")\n\n    # condition_smoothness=False (default) must stay byte-for-byte identical too,\n    # and =True must actually change the output when the scalar changes.\n    assert not hasattr(plain, \"smoothness_to_bias\"), \"default field must not carry the smoothness bias at all\"\n    sv = CausalVelocityField(grid_hw = (8, 8), dim = dim, depth = 2, heads = 2, dim_head = 16,\n                             condition_smoothness = True)\n    lo = torch.zeros(b)\n    hi = torch.ones(b)\n    v_lo, _ = sv.forward(grid, object_features, capability, rank, movable, smoothness_cond = lo)\n    v_hi, _ = sv.forward(grid, object_features, capability, rank, movable, smoothness_cond = hi)\n    assert not torch.allclose(v_lo, v_hi), \"smoothness_cond=0 vs 1 produced identical output\"\n    try:\n        sv.forward(grid, object_features, capability, rank, movable)\n        raise AssertionError(\"condition_smoothness=True must require smoothness_cond, not silently default it\")\n    except AssertionError as e:\n        if \"requires smoothness_cond\" not in str(e):\n            raise\n    print(\"ok condition_smoothness=True: output actually depends on the scalar, and is required\")\n\n\n# ---- target_flow ----\nimport math\n\n\n\n\ndef selection_mask(logits, available):\n    return available \u0026 (logits \u003e 0)\n\n\ndef priority_scale(raw, minimum=0.05, maximum=0.5):\n    \"\"\"Smooth bounded Gaussian scale; no hard-clamp dead zone.\"\"\"\n    return minimum + (maximum - minimum) * torch.sigmoid(raw)\n\n\ndef selected_ranks(rank, available):\n    n = rank.shape[-1]\n    selected = available \u0026 (rank \u003e= 0) \u0026 (rank \u003c n)\n    # zeros_like+n rather than full_like(rank, n): identical result, but the NPU\n    # compiler's tvm frontend mishandles full_like with a scalar fill.\n    return torch.where(selected, rank, torch.zeros_like(rank) + n), selected\n\n\ndef rank_selected(priority, selected, limit=None):\n    \"\"\"Ascending sampled priorities; omitted objects use the N sentinel.\"\"\"\n    n = priority.shape[-1]\n    if limit is not None and limit \u003c 0:\n        raise ValueError(\"interaction limit must be nonnegative\")\n    order = priority.masked_fill(~selected, float('inf')).argsort(dim=-1, stable=True)\n    rank = torch.empty_like(order).scatter_(\n        1, order, torch.arange(n, device=order.device).expand_as(order))\n    active = selected \u0026 (rank \u003c (n if limit is None else limit))\n    return torch.where(active, rank, torch.full_like(rank, n)), active\n\n\ndef time_embedding(t, dim):\n    half = dim // 2\n    freqs = torch.exp(-math.log(1000.0) * torch.arange(half, device=t.device, dtype=t.dtype) / max(1, half - 1))\n    a = t[..., None] * freqs\n    return torch.cat([a.sin(), a.cos()], dim=-1)\n\n\ndef target_velocity(static, context, scene, g_t, t, rank, available,\n                    cfg_in, trunk, head, time_dim, causal=True, key_mask=None,\n                    causal_bias_slope=0.0):\n    \"\"\"Shared Stage B implementation; modules remain owned by each checkpoint.\n\n    `key_mask` (b, 1 + n + s + n) bool marks keys that exist: padded object or\n    scene slots are never read. None keeps the fixed-size behaviour unchanged.\n\n    `causal_bias_slope`: soft-causal ablation (see causal_velocity_field.\n    causal_bias). Only meaningful with causal=False -- it grades the\n    movable-to-movable penalty instead of leaving it at zero. 0.0 (default)\n    is a no-op, byte-for-byte the pre-existing behaviour.\n    \"\"\"\n    rank, selected = selected_ranks(rank, available)\n    g_t = torch.where(selected[..., None], g_t, torch.zeros_like(g_t))\n    b, n, _ = static.shape\n    te = time_embedding(t, time_dim)[:, None].expand(b, n, time_dim)\n    obj = cfg_in(torch.cat([static, g_t, te], dim=-1))\n    # A rank restriction applies to generated decisions, never to currently\n    # observed geometry. Separate read-only copies expose ALL observed objects,\n    # including selected objects whose generated targets must remain hidden.\n    observed = cfg_in(torch.cat([static, torch.zeros_like(g_t), te], dim=-1))\n    tokens = torch.cat([context, obj, scene, observed], dim=1)\n    mask = causal_mask(rank, selected, scene.shape[1] + n, causal=causal)\n    bias = (causal_bias(rank, selected, scene.shape[1] + n, causal_bias_slope)\n            if causal_bias_slope else None)\n    if key_mask is not None:\n        if key_mask.shape != mask.shape[:2]:\n            raise ValueError(\"key_mask must cover context, objects, scene and observed copies\")\n        mask = mask | ~key_mask[:, None, :]\n    return head(trunk(tokens, mask=mask, bias=bias)[:, 1:1 + n])\n\n\nclass RankCausalTargetFlow(nn.Module):\n    def __init__(self, dim, target_dim, depth=4, heads=4, dim_head=32, causal=True,\n                 causal_bias_slope=0.0):\n        super().__init__()\n        if dim % 4:\n            raise ValueError(\"target flow dim must be divisible by 4\")\n        self.dim, self.target_dim, self.causal = dim, target_dim, causal\n        self.noise_std = 1.0\n        self.causal_bias_slope = float(causal_bias_slope)  # soft-causal ablation, see causal_velocity_field.causal_bias\n        self.cfg_in = nn.Sequential(nn.Linear(dim + target_dim + dim // 2, dim),\n                                    nn.GELU(), nn.Linear(dim, dim))\n        self.trunk = AffordanceTransformer(dim, depth=depth, heads=heads, dim_head=dim_head)\n        self.head = nn.Sequential(nn.LayerNorm(dim), nn.Linear(dim, dim), nn.GELU(),\n                                  nn.Linear(dim, target_dim))\n\n    def forward(self, static, context, scene, g_t, t, rank, selected, key_mask=None):\n        return target_velocity(static, context, scene, g_t, t, rank, selected,\n                               self.cfg_in, self.trunk, self.head, self.dim // 2, self.causal,\n                               key_mask=key_mask, causal_bias_slope=self.causal_bias_slope)\n\n    @torch.no_grad()\n    def sample(self, static, context, scene, rank, selected, n_steps=30, generator=None,\n               key_mask=None, trace=None):\n        \"\"\"`trace`, if a list, receives (t, state) at every Euler step and at t=1.\n\n        The states are the generator's own intermediates. They exist so a figure\n        can show the flow evolving instead of an interpolation of its endpoint;\n        nothing in the planner reads them and the default path is unchanged.\n        \"\"\"\n        if n_steps \u003c= 0:\n            raise ValueError(\"n_steps must be positive\")\n        rank, selected = selected_ranks(rank, selected)\n        g = torch.randn(*static.shape[:2], self.target_dim, device=static.device,\n                        dtype=static.dtype, generator=generator) * self.noise_std\n        g = torch.where(selected[..., None], g, torch.zeros_like(g))\n        for k in range(n_steps):\n            t = torch.full((static.shape[0],), k / n_steps, device=static.device, dtype=static.dtype)\n            if trace is not None:\n                trace.append((k / n_steps, g.detach().clone()))\n            v = self(static, context, scene, g, t, rank, selected, key_mask=key_mask)\n            g = g + torch.where(selected[..., None], v, torch.zeros_like(v)) / n_steps\n        if trace is not None:\n            trace.append((1.0, g.detach().clone()))\n        return g\n","lines":["\u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;causalflownet: causal_velocity_field, target_flow.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003ecausal_velocity_field: Causal velocity field (Stage B): tau-ordered attention -\u0026gt; path velocity.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003eOnce the priority head has committed an ordering, object i may read only\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003eobjects that move at-or-before its own turn; the embodiment token, scene\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003etokens and immovable objects are static context readable by everyone. The\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003ehead regresses velocity in each object\u0026#x27;s OWN path time, so the regression\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003etarget is schedule-independent (vanilla conditional flow matching).\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003eThe mask rule that matters (learned the hard way, kept as a gradient test):\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003econtext tokens may NOT read movable objects. If they could, a later object\u0026#x27;s\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003epose would reach an earlier object through a 2-hop path -- late object -\u0026gt;\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003econtext token at layer L -\u0026gt; early object at layer L+1.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003eein notation:\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e  b - batch\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e  n - objects\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e  t - tokens (1 capability + n objects + s scene)\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003etarget_flow: CLEAR\u0026#x27;s task-independent selected-object, order-conditioned target flow.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003eFlow time is generative time, not controller execution time. Static observations\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003eare available at every rank; later generated targets are not. Domain adapters\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003eprovide object/context tokens and interpret/project the final configuration code.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","","\u003cspan class=\"tok-comment\"\u003e# ---- causal_velocity_field ----\u003c/span\u003e","\u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e torch","\u003cspan class=\"tok-keyword\"\u003efrom\u003c/span\u003e torch \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e nn","\u003cspan class=\"tok-keyword\"\u003efrom\u003c/span\u003e torch.nn \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e Module","","\u003cspan class=\"tok-keyword\"\u003efrom\u003c/span\u003e clear.model.affordancenet \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e AffordanceTransformer","\u003cspan class=\"tok-keyword\"\u003efrom\u003c/span\u003e clear.model.encoders \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e CapabilityEncoder","\u003cspan class=\"tok-keyword\"\u003efrom\u003c/span\u003e clear.model.encoders \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e SCENE_CHANS, SceneEncoder, obj_feat_dim","\u003cspan class=\"tok-keyword\"\u003efrom\u003c/span\u003e clear.util \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e wall_oob_penalty","","\u003cspan class=\"tok-keyword\"\u003efrom\u003c/span\u003e clear.model.affordancenet \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e StageBAuxHeads","","\u003cspan class=\"tok-comment\"\u003e# causal mask\u003c/span\u003e","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003ecausal_mask\u003c/span\u003e(rank, movable, n_scene, causal = \u003cspan class=\"tok-keyword\"\u003eTrue\u003c/span\u003e):","    \u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;(b, t, t) bool, True = blocked.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    A movable object key may be read ONLY by a movable object query with an\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    equal-or-later rank. Every other token may read anything EXCEPT movable\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    objects (the 2-hop rule above).\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    causal=False = OBSERVATION-CONSISTENT attention (2026-08-26, adopted after\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    experiments/ordering_ablation: abstract plan success 0.30 -\u0026gt; 0.86 at k=3,\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    physical nocausal_s0 0.920 vs 0.884, PLAN sect95/97): every movable object\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    reads every movable object regardless of rank. This is not a leak of future\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    information: under the slot schedule (util.schedule.oracle_progress) a\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    later-ranked object sits at its current pose x0 while an earlier one moves,\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    i.e. exactly what the robot observes at that moment; earlier-ranked objects\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    are read at their parked pose, which is what the robot will observe once they\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    have been executed. clear.PAMO.forward asserts that invariant\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    (_assert_observation_consistent). The context rule (cap/scene/immovable\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    tokens never read movable objects) is kept as is. causal=True is the legacy\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    rank-causal mask, kept for the ablation and for older checkpoints.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    \u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","    b, n = rank.shape","    t = \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e + n + n_scene","    mask = torch.zeros(b, t, t, dtype = torch.bool, device = rank.device)","","    key_is_movable = torch.zeros(b, t, dtype = torch.bool, device = rank.device)","    key_is_movable[:, \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e:\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e + n] = movable","    mask |= key_is_movable[:, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e, :]","","    allowed = movable[:, :, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e] \u0026amp; movable[:, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e, :]","    \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e causal:","        key_is_later = rank[:, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e, :] \u0026gt; rank[:, :, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e]","        allowed = allowed \u0026amp; ~key_is_later","    mask[:, \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e:\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e + n, \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e:\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e + n] \u0026amp;= ~allowed","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e mask","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003ecausal_bias\u003c/span\u003e(rank, movable, n_scene, slope):","    \u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;(b, t, t) float, additive attention-logit penalty for the SOFT causal\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    variant (2026-09-12): rather than hard-blocking a later-ranked movable\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    key (causal=True) or leaving it fully open (causal=False, the existing\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    no_causal_mask ablation, checked in RESULTS.md and NOT found necessary --\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    held-out CI [-1.83, +4.92]), grade the penalty by how much later it is.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    slope=0 reduces to causal=False exactly; used with causal=False so the\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    2-hop context rule (context tokens never read movable objects) stays the\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    one hard invariant causal_mask always enforces. Caller passes the SAME\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    `rank`/`movable` (selected) tensors given to causal_mask(..., causal=False).\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    \u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","    b, n = rank.shape","    t = \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e + n + n_scene","    bias = rank.new_zeros(b, t, t, dtype = torch.float32)","    allowed = movable[:, :, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e] \u0026amp; movable[:, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e, :]","    rank_gap = (rank[:, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e, :] - rank[:, :, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e]).clamp(min = \u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e).to(torch.float32)","    bias[:, \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e:\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e + n, \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e:\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e + n] = torch.where(allowed, -slope * rank_gap, torch.zeros_like(rank_gap))","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e bias","","\u003cspan class=\"tok-comment\"\u003e# causal velocity field\u003c/span\u003e","","","\u003cspan class=\"tok-keyword\"\u003eclass\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003eCausalVelocityField\u003c/span\u003e(StageBAuxHeads, Module):","    \u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003e__init__\u003c/span\u003e(\u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e, grid_hw = (\u003cspan class=\"tok-number\"\u003e8\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e8\u003c/span\u003e), dim = \u003cspan class=\"tok-number\"\u003e128\u003c/span\u003e, depth = \u003cspan class=\"tok-number\"\u003e4\u003c/span\u003e, heads = \u003cspan class=\"tok-number\"\u003e4\u003c/span\u003e, dim_head = \u003cspan class=\"tok-number\"\u003e32\u003c/span\u003e,","                 drop_obj = (), obj_extra_dim = \u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e, predict_robot_path = \u003cspan class=\"tok-keyword\"\u003eFalse\u003c/span\u003e,","                 condition_smoothness = \u003cspan class=\"tok-keyword\"\u003eFalse\u003c/span\u003e, include_reachable = \u003cspan class=\"tok-keyword\"\u003eFalse\u003c/span\u003e,","                 predict_feasibility = \u003cspan class=\"tok-keyword\"\u003eFalse\u003c/span\u003e, predict_affordance = \u003cspan class=\"tok-keyword\"\u003eFalse\u003c/span\u003e, causal = \u003cspan class=\"tok-keyword\"\u003eTrue\u003c/span\u003e,","                 capability_encoder = \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e,","                 scene_channels = SCENE_CHANS):","        super().__init__()","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.causal = causal  \u003cspan class=\"tok-comment\"\u003e# False = no_causal_mask ablation, see causal_mask()\u003c/span\u003e","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.to_object_tokens = nn.Linear(obj_feat_dim(drop_obj, include_reachable) + obj_extra_dim, dim)","        \u003cspan class=\"tok-comment\"\u003e# capability_encoder: optional module replacing the default vector\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# encoder (e.g. kappa_set_encoder.KappaSetEncoder); must map its own\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# `capability` input to a (b, 1, dim) token.\u003c/span\u003e","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.capability_encoder = capability_encoder \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e capability_encoder \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eelse\u003c/span\u003e CapabilityEncoder(dim)","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.scene_encoder = SceneEncoder(dim, grid_hw, channels = scene_channels)","        \u003cspan class=\"tok-comment\"\u003e# OPT-IN, same contract as predict_robot_path below: condition_smoothness=False\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# (the default) leaves this class byte-for-byte the old CausalVelocityField --\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# no extra params, forward()\u0026#x27;s signature accepts `smoothness` but ignores it.\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# When on, a scalar in [0, 1] biases the capability token via a small additive\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# projection (not a new token -- inserting one would shift every index the\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# causal mask and the `tokens[:, 1:1+n]` slicing below already hardcode).\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# `clear/data/data.py`\u0026#x27;s `collate(..., smoothness=True)` supplies the matching\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# TRAINING label: pose/v_target blended toward a Chaikin-smoothed path by the\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# same scalar, so the network learns what \u0026quot;more smoothness\u0026quot; should look like\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# rather than only being told to reproduce it post-hoc (see\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# PAMO.sample_robot_path\u0026#x27;s own, unrelated, post-hoc EMA `smoothness` param --\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# deliberately named `smoothness_cond` everywhere in this class to not collide).\u003c/span\u003e","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.condition_smoothness = condition_smoothness","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e condition_smoothness:","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.smoothness_to_bias = nn.Linear(\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e, dim)","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.transformer = AffordanceTransformer(dim, depth = depth, heads = heads, dim_head = dim_head)","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.to_velocity = nn.Sequential(","            nn.Linear(dim, dim),","            nn.GELU(),","            nn.Linear(dim, \u003cspan class=\"tok-number\"\u003e3\u003c/span\u003e),","        )","        \u003cspan class=\"tok-comment\"\u003e# Second head off the same trunk: where does this object END UP,\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# globally (x1 - current pose) -- not just its local path velocity.\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# flow_loss alone only ever sees the next instant; this is the signal\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# that lets training penalize an invalid *resulting* world (see\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# util/validity.py), which the velocity head has no way to express.\u003c/span\u003e","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.to_endpoint = nn.Sequential(","            nn.Linear(dim, dim),","            nn.GELU(),","            nn.Linear(dim, \u003cspan class=\"tok-number\"\u003e3\u003c/span\u003e),","        )","","        \u003cspan class=\"tok-comment\"\u003e# Third pair of heads, OPT-IN (predict_robot_path=False leaves this\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# class byte-for-byte the old CausalVelocityField -- both existing\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# call sites in clear.py unpack exactly 2 return values and must not\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# break). Reads the SAME per-object transformer output as\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# to_velocity/to_endpoint -- no new token, no rank/mask change, so\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# none of the causal-mask correctness work above is touched. The\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# physical quantity is different (the ROBOT\u0026#x27;s own path to reach this\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# object, not the object\u0026#x27;s own placement) but the object\u0026#x27;s token\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# already carries everything the mask says it may see (earlier-turn\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# objects\u0026#x27; outcomes, capability, scene) -- see module docstring in\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# clear/data/waypoint_data.py for what supplies the training label\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# (Roadmap.path_points, not this repo\u0026#x27;s grid cell_path -- that labels\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# OBJECT motion, this labels ROBOT motion, a different quantity that\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# happens to reuse the same pose/velocity CFM parameterisation).\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e#\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# Robot position between phases is approximated as the causally\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# PREVIOUS object\u0026#x27;s own endpoint (where the robot just finished\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# pushing it to) -- or the scene\u0026#x27;s start pose for the first-ranked\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# object. This needs no new input signal (rank + x1 already exist in\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# the sequence); it is an approximation, not measured, and is the\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# first thing to revisit if predicted robot paths look wrong at a\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# phase boundary. See experiments/e4/HANDOFF_sumo_executor.md\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# \u0026quot;\uc2a4\ubb3c\uc77c\uacf1 \ubc88\uc9f8 \ud6c4\uc18d\u0026quot;.\u003c/span\u003e","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.predict_robot_path = predict_robot_path","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e predict_robot_path:","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.to_robot_velocity = nn.Sequential(nn.Linear(dim, dim), nn.GELU(), nn.Linear(dim, \u003cspan class=\"tok-number\"\u003e3\u003c/span\u003e))","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.to_robot_endpoint = nn.Sequential(nn.Linear(dim, dim), nn.GELU(), nn.Linear(dim, \u003cspan class=\"tok-number\"\u003e3\u003c/span\u003e))","","        \u003cspan class=\"tok-comment\"\u003e# Fourth head, OPT-IN (predict_feasibility=False leaves this class\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# byte-for-byte the old CausalVelocityField, same contract as\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# predict_robot_path/condition_smoothness above -- forward()\u0026#x27;s\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# existing 2-value return is untouched, only forward_with_feasibility\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# below uses this). 2026-08-23, PLAN doc S54-62 / experiments/\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# stageb_clearance_signal/RESULTS.md sect9-10: an RL reward built\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# from the SAME validated signal (order_index/push_distance/n_movers/\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# wall-occupancy, sect4-6\u0026#x27;s v4/v5 feature set) made real placement\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# accuracy WORSE, not better (miss rate 17.2% -\u0026gt; 41.6%, sect9) --\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# consistent overoptimization of an imperfect frozen critic via\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# noisy policy gradient. This head instead trains the SAME kind of\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# signal via ordinary supervised backprop, directly into the shared\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# trunk, alongside flow_loss/endpoint_loss -- no policy-gradient\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# variance, no frozen numpy critic to game. Takes the trunk\u0026#x27;s own\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# per-object hidden state PLUS 4 scalars the trunk alone cannot see\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# (they depend on the CANDIDATE endpoint this same forward pass just\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# produced, not just the pre-placement context the trunk attends\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# over): push_distance (from endpoint_delta, literally free --\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# already computed for endpoint_loss), wall_occ (reuses\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# wall_oob_penalty\u0026#x27;s own differentiable bilinear sample, not a new\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# geometry channel), order_index/n_movers (from `rank`/`movable`,\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# already in every batch -- v4/v5\u0026#x27;s single strongest and third-\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# strongest univariate features, sect6, never before given to any\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# head as an explicit input). Outputs a per-object SUCCESS LOGIT,\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# trained with BCEWithLogitsLoss against real physical phase-level\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# outcomes (the same ~3-4k-row corpus feasibility_critic.py already\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# builds) -- see clear.py\u0026#x27;s feasibility_forward for the loss, only\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# meaningful on batches carrying real labels (see\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# data/real_corpus.py\u0026#x27;s build_feasibility_batches).\u003c/span\u003e","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.predict_feasibility = predict_feasibility","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e predict_feasibility:","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.to_feasibility = nn.Sequential(nn.Linear(dim + \u003cspan class=\"tok-number\"\u003e4\u003c/span\u003e, dim), nn.GELU(), nn.Linear(dim, \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e))","            \u003cspan class=\"tok-comment\"\u003e# Residual refinement head (2026-08-23, PLAN doc S54-62 sect16 --\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# experiments/stageb_clearance_signal/RESULTS.md): the actual\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# CE-Adapter/CrossTracer mechanism (T_e = T_init + Delta_e), which\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# sect10\u0026#x27;s feasibility head alone did NOT implement -- confirmed\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# directly by reading PAMO.sample()\u0026#x27;s own ODE loop: it integrates\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# `velocity` only and DISCARDS endpoint_delta entirely (`_` in\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# `velocity, _ = self.velocity_field(...)`), so nothing built in\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# sect10 could ever have reached actual sampled behavior except\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# indirectly, through gradient shared with the trunk that also\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# produces `velocity` -- a real, but diffuse and unconstrained,\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# coupling, consistent with sect12/15\u0026#x27;s small, seed-noisy effect.\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# Same `feas_in` input as to_feasibility (same 4 context scalars\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# + trunk state); output is a BOUNDED xy correction (delta_max,\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# tanh-squashed -- CrossTracer\u0026#x27;s own bounding, and this\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# project\u0026#x27;s own S54-62 audit (sect8) already found an unbounded\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# correction path is exactly how a reward gets gamed).\u003c/span\u003e","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.delta_max = \u003cspan class=\"tok-number\"\u003e1.5\u003c/span\u003e  \u003cspan class=\"tok-comment\"\u003e# grid cells -- generously covers sect6\u0026#x27;s push_distance\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# dose-response finding (the \u0026quot;sweet spot\u0026quot; sat around 2 cells, the cliff past ~4;\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# 1.5 lets the residual meaningfully relocate a placement without being able to\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# single-handedly walk it out to the danger zone sect6 found)\u003c/span\u003e","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.to_residual = nn.Sequential(nn.Linear(dim + \u003cspan class=\"tok-number\"\u003e4\u003c/span\u003e, dim), nn.GELU(), nn.Linear(dim, \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e))","","        \u003cspan class=\"tok-comment\"\u003e# Fifth head pair, OPT-IN (predict_affordance=False leaves this class\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# byte-for-byte the old one, same contract as every flag above).\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# 2026-08-24, RESULTS.md sect22-23: embodiment-conditioned AFFORDANCE\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# MAP -- per-object (h, w) logits over park cells, supervised by\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# clear/data/affordance.py\u0026#x27;s dense oracle labels (oracle.park_valid,\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# 12 maps/scene, unlimited volume -- the label starvation that sank\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# sect10-22\u0026#x27;s per-object-scalar heads does not apply). Standalone\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# Phase-1 net already cleared the pre-stated gates (held-out per-cell\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# AUC 0.988, every embodiment \u0026gt;= 0.984 -- train_affordance.py); this\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# head asks whether the SAME signal can flow through PAMO\u0026#x27;s own\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# trunk. Mechanism: object token (query) x scene token (key) dot\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# product -\u0026gt; coarse (4,4) map in the scene encoder\u0026#x27;s own token\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# layout, bilinearly upsampled and refined by a small conv decoder\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# that re-reads the raw class grid (full-res wall structure the 16\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# coarse tokens can\u0026#x27;t carry). The causal mask already lets every\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# object token read every scene token, and scene tokens never read\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# movable objects -- so the affordance query is object-conditioned\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# while the keys stay object-independent, and NOTHING about the mask\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# changes.\u003c/span\u003e","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.predict_affordance = predict_affordance","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e predict_affordance:","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.to_afford_q = nn.Linear(dim, dim)","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.to_afford_k = nn.Linear(dim, dim)","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.afford_decoder = nn.Sequential(","                nn.Conv2d(\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e + \u003cspan class=\"tok-number\"\u003e5\u003c/span\u003e, dim // \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e3\u003c/span\u003e, padding = \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e), nn.GELU(),","                nn.Conv2d(dim // \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, dim // \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e3\u003c/span\u003e, padding = \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e), nn.GELU(),","                nn.Conv2d(dim // \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e),","            )","","    \u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003eforward\u003c/span\u003e(\u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e, grid, object_features, capability, rank, movable, context = \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e,","                smoothness_cond = \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e):","        \u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;-\u0026gt; (velocity, endpoint_delta), each (b, n, 3). velocity is in each\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        object\u0026#x27;s own path time; endpoint_delta estimates x1 - pose (used only\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        as an auxiliary training signal -- sample() ignores it, the rollout\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        is still pure CFM integration).\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        `context`: see PriorityHead.forward. The mask reads the scene-token\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        count off the tensor rather than off self.scene_encoder, so a front end\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        with a different token count cannot silently mis-mask.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        `smoothness_cond`: (b,) in [0, 1], only read when condition_smoothness=True\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        (required then -- see __init__).\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        \u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","        out = \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e._trunk_out(grid, object_features, capability, rank, movable, context, smoothness_cond)","        \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.to_velocity(out), \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.to_endpoint(out)","","    \u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003e_trunk_out\u003c/span\u003e(\u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e, grid, object_features, capability, rank, movable, context = \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e,","                   smoothness_cond = \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e):","        full, n = \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e._trunk_full(grid, object_features, capability, rank, movable, context,","                                   smoothness_cond)","        \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e full[:, \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e:\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e + n]","","    \u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003e_trunk_full\u003c/span\u003e(\u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e, grid, object_features, capability, rank, movable, context = \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e,","                    smoothness_cond = \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e):","        \u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;-\u0026gt; (all transformer token outputs (b, 1+n+s, d), n). _trunk_out is\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        the [1:1+n] object slice of this -- one shared implementation so the\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        affordance head\u0026#x27;s scene-token reads can never drift from what the\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        object heads were computed with.\u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","        objects = \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.to_object_tokens(object_features)","        cap_token, scene_tokens = context \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e context \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eelse\u003c/span\u003e (","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.capability_encoder(capability), \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.scene_encoder(grid))","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.condition_smoothness:","            \u003cspan class=\"tok-keyword\"\u003eassert\u003c/span\u003e smoothness_cond \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e, \u003cspan class=\"tok-string\"\u003e\u0026quot;condition_smoothness=True requires smoothness_cond\u0026quot;\u003c/span\u003e","            cap_token = cap_token + \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.smoothness_to_bias(smoothness_cond.view(-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e))[:, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e, :]","        tokens = torch.cat([cap_token, objects, scene_tokens], dim = \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e)","","        mask = causal_mask(rank, movable, scene_tokens.shape[\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e], causal = \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.causal)","        \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.transformer(tokens, mask = mask), objects.shape[\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e]","","    \u003cspan class=\"tok-comment\"\u003e# forward_with_{robot_path,feasibility,affordance} live in stageb_aux_heads.py (mixin)\u003c/span\u003e","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003e_self_check\u003c/span\u003e():","    \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e torch","","    \u003cspan class=\"tok-keyword\"\u003efrom\u003c/span\u003e clear.data.capability \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e FEATURE_DIM","    \u003cspan class=\"tok-keyword\"\u003efrom\u003c/span\u003e clear.model.encoders \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e obj_feat_dim","","    torch.manual_seed(\u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e)","    b, n, dim = \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e4\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e32\u003c/span\u003e","    grid = torch.zeros(b, \u003cspan class=\"tok-number\"\u003e5\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e8\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e8\u003c/span\u003e)","    object_features = torch.randn(b, n, obj_feat_dim(()))","    capability = torch.randn(b, FEATURE_DIM)","    rank = torch.stack([torch.randperm(n) \u003cspan class=\"tok-keyword\"\u003efor\u003c/span\u003e _ \u003cspan class=\"tok-keyword\"\u003ein\u003c/span\u003e range(b)])","    movable = torch.ones(b, n, dtype = torch.bool)","","    \u003cspan class=\"tok-comment\"\u003e# predict_robot_path=False (the default, and what PAMO/MazePAMO\u0026#x27;s existing\u003c/span\u003e","    \u003cspan class=\"tok-comment\"\u003e# 2 call sites unpack) must be byte-for-byte the pre-extension class.\u003c/span\u003e","    plain = CausalVelocityField(grid_hw = (\u003cspan class=\"tok-number\"\u003e8\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e8\u003c/span\u003e), dim = dim, depth = \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, heads = \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, dim_head = \u003cspan class=\"tok-number\"\u003e16\u003c/span\u003e)","    \u003cspan class=\"tok-keyword\"\u003eassert\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e hasattr(plain, \u003cspan class=\"tok-string\"\u003e\u0026quot;to_robot_velocity\u0026quot;\u003c/span\u003e), \u003cspan class=\"tok-string\"\u003e\u0026quot;default field must not carry robot heads at all\u0026quot;\u003c/span\u003e","    v, e = plain.forward(grid, object_features, capability, rank, movable)","    \u003cspan class=\"tok-keyword\"\u003eassert\u003c/span\u003e v.shape == (b, n, \u003cspan class=\"tok-number\"\u003e3\u003c/span\u003e) \u003cspan class=\"tok-keyword\"\u003eand\u003c/span\u003e e.shape == (b, n, \u003cspan class=\"tok-number\"\u003e3\u003c/span\u003e)","    print(\u003cspan class=\"tok-string\"\u003e\u0026quot;ok predict_robot_path=False: no robot heads, forward() shape unchanged\u0026quot;\u003c/span\u003e)","","    reachable_feats = torch.randn(b, n, obj_feat_dim((), include_reachable = \u003cspan class=\"tok-keyword\"\u003eTrue\u003c/span\u003e))","    with_reachable = CausalVelocityField(grid_hw = (\u003cspan class=\"tok-number\"\u003e8\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e8\u003c/span\u003e), dim = dim, depth = \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, heads = \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e,","                                         dim_head = \u003cspan class=\"tok-number\"\u003e16\u003c/span\u003e, include_reachable = \u003cspan class=\"tok-keyword\"\u003eTrue\u003c/span\u003e)","    v, e = with_reachable.forward(grid, reachable_feats, capability, rank, movable)","    \u003cspan class=\"tok-keyword\"\u003eassert\u003c/span\u003e v.shape == (b, n, \u003cspan class=\"tok-number\"\u003e3\u003c/span\u003e) \u003cspan class=\"tok-keyword\"\u003eand\u003c/span\u003e e.shape == (b, n, \u003cspan class=\"tok-number\"\u003e3\u003c/span\u003e)","    print(\u003cspan class=\"tok-string\"\u003e\u0026quot;ok include_reachable=True: to_object_tokens sized for the extra column\u0026quot;\u003c/span\u003e)","","    vf = CausalVelocityField(grid_hw = (\u003cspan class=\"tok-number\"\u003e8\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e8\u003c/span\u003e), dim = dim, depth = \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, heads = \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, dim_head = \u003cspan class=\"tok-number\"\u003e16\u003c/span\u003e,","                             predict_robot_path = \u003cspan class=\"tok-keyword\"\u003eTrue\u003c/span\u003e)","    v2, e2, rv, re = vf.forward_with_robot_path(grid, object_features, capability, rank, movable)","    \u003cspan class=\"tok-keyword\"\u003eassert\u003c/span\u003e rv.shape == (b, n, \u003cspan class=\"tok-number\"\u003e3\u003c/span\u003e) \u003cspan class=\"tok-keyword\"\u003eand\u003c/span\u003e re.shape == (b, n, \u003cspan class=\"tok-number\"\u003e3\u003c/span\u003e)","    \u003cspan class=\"tok-keyword\"\u003eassert\u003c/span\u003e torch.isfinite(rv).all() \u003cspan class=\"tok-keyword\"\u003eand\u003c/span\u003e torch.isfinite(re).all()","    v3, e3 = vf.forward(grid, object_features, capability, rank, movable)","    \u003cspan class=\"tok-keyword\"\u003eassert\u003c/span\u003e torch.allclose(v2, v3) \u003cspan class=\"tok-keyword\"\u003eand\u003c/span\u003e torch.allclose(e2, e3), (","        \u003cspan class=\"tok-string\"\u003e\u0026quot;forward() and forward_with_robot_path() must share the identical trunk output\u0026quot;\u003c/span\u003e)","    print(\u003cspan class=\"tok-string\"\u003e\u0026quot;ok predict_robot_path=True: robot heads present, shared trunk output matches forward()\u0026quot;\u003c/span\u003e)","","    (rv.sum() + re.sum()).backward()","    print(\u003cspan class=\"tok-string\"\u003e\u0026quot;ok gradients reach the robot-path heads\u0026quot;\u003c/span\u003e)","","    \u003cspan class=\"tok-comment\"\u003e# condition_smoothness=False (default) must stay byte-for-byte identical too,\u003c/span\u003e","    \u003cspan class=\"tok-comment\"\u003e# and =True must actually change the output when the scalar changes.\u003c/span\u003e","    \u003cspan class=\"tok-keyword\"\u003eassert\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e hasattr(plain, \u003cspan class=\"tok-string\"\u003e\u0026quot;smoothness_to_bias\u0026quot;\u003c/span\u003e), \u003cspan class=\"tok-string\"\u003e\u0026quot;default field must not carry the smoothness bias at all\u0026quot;\u003c/span\u003e","    sv = CausalVelocityField(grid_hw = (\u003cspan class=\"tok-number\"\u003e8\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e8\u003c/span\u003e), dim = dim, depth = \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, heads = \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, dim_head = \u003cspan class=\"tok-number\"\u003e16\u003c/span\u003e,","                             condition_smoothness = \u003cspan class=\"tok-keyword\"\u003eTrue\u003c/span\u003e)","    lo = torch.zeros(b)","    hi = torch.ones(b)","    v_lo, _ = sv.forward(grid, object_features, capability, rank, movable, smoothness_cond = lo)","    v_hi, _ = sv.forward(grid, object_features, capability, rank, movable, smoothness_cond = hi)","    \u003cspan class=\"tok-keyword\"\u003eassert\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e torch.allclose(v_lo, v_hi), \u003cspan class=\"tok-string\"\u003e\u0026quot;smoothness_cond=0 vs 1 produced identical output\u0026quot;\u003c/span\u003e","    \u003cspan class=\"tok-keyword\"\u003etry\u003c/span\u003e:","        sv.forward(grid, object_features, capability, rank, movable)","        \u003cspan class=\"tok-keyword\"\u003eraise\u003c/span\u003e AssertionError(\u003cspan class=\"tok-string\"\u003e\u0026quot;condition_smoothness=True must require smoothness_cond, not silently default it\u0026quot;\u003c/span\u003e)","    \u003cspan class=\"tok-keyword\"\u003eexcept\u003c/span\u003e AssertionError \u003cspan class=\"tok-keyword\"\u003eas\u003c/span\u003e e:","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e \u003cspan class=\"tok-string\"\u003e\u0026quot;requires smoothness_cond\u0026quot;\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003ein\u003c/span\u003e str(e):","            \u003cspan class=\"tok-keyword\"\u003eraise\u003c/span\u003e","    print(\u003cspan class=\"tok-string\"\u003e\u0026quot;ok condition_smoothness=True: output actually depends on the scalar, and is required\u0026quot;\u003c/span\u003e)","","","\u003cspan class=\"tok-comment\"\u003e# ---- target_flow ----\u003c/span\u003e","\u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e math","","","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003eselection_mask\u003c/span\u003e(logits, available):","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e available \u0026amp; (logits \u0026gt; \u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e)","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003epriority_scale\u003c/span\u003e(raw, minimum=\u003cspan class=\"tok-number\"\u003e0.05\u003c/span\u003e, maximum=\u003cspan class=\"tok-number\"\u003e0.5\u003c/span\u003e):","    \u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;Smooth bounded Gaussian scale; no hard-clamp dead zone.\u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e minimum + (maximum - minimum) * torch.sigmoid(raw)","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003eselected_ranks\u003c/span\u003e(rank, available):","    n = rank.shape[-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e]","    selected = available \u0026amp; (rank \u0026gt;= \u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e) \u0026amp; (rank \u0026lt; n)","    \u003cspan class=\"tok-comment\"\u003e# zeros_like+n rather than full_like(rank, n): identical result, but the NPU\u003c/span\u003e","    \u003cspan class=\"tok-comment\"\u003e# compiler\u0026#x27;s tvm frontend mishandles full_like with a scalar fill.\u003c/span\u003e","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e torch.where(selected, rank, torch.zeros_like(rank) + n), selected","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003erank_selected\u003c/span\u003e(priority, selected, limit=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e):","    \u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;Ascending sampled priorities; omitted objects use the N sentinel.\u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","    n = priority.shape[-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e]","    \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e limit \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eand\u003c/span\u003e limit \u0026lt; \u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e:","        \u003cspan class=\"tok-keyword\"\u003eraise\u003c/span\u003e ValueError(\u003cspan class=\"tok-string\"\u003e\u0026quot;interaction limit must be nonnegative\u0026quot;\u003c/span\u003e)","    order = priority.masked_fill(~selected, float(\u003cspan class=\"tok-string\"\u003e\u0026#x27;inf\u0026#x27;\u003c/span\u003e)).argsort(dim=-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e, stable=\u003cspan class=\"tok-keyword\"\u003eTrue\u003c/span\u003e)","    rank = torch.empty_like(order).scatter_(","        \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e, order, torch.arange(n, device=order.device).expand_as(order))","    active = selected \u0026amp; (rank \u0026lt; (n \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e limit \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eelse\u003c/span\u003e limit))","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e torch.where(active, rank, torch.full_like(rank, n)), active","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003etime_embedding\u003c/span\u003e(t, dim):","    half = dim // \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e","    freqs = torch.exp(-math.log(\u003cspan class=\"tok-number\"\u003e1000.0\u003c/span\u003e) * torch.arange(half, device=t.device, dtype=t.dtype) / max(\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e, half - \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e))","    a = t[..., \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e] * freqs","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e torch.cat([a.sin(), a.cos()], dim=-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e)","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003etarget_velocity\u003c/span\u003e(static, context, scene, g_t, t, rank, available,","                    cfg_in, trunk, head, time_dim, causal=\u003cspan class=\"tok-keyword\"\u003eTrue\u003c/span\u003e, key_mask=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e,","                    causal_bias_slope=\u003cspan class=\"tok-number\"\u003e0.0\u003c/span\u003e):","    \u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;Shared Stage B implementation; modules remain owned by each checkpoint.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    `key_mask` (b, 1 + n + s + n) bool marks keys that exist: padded object or\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    scene slots are never read. None keeps the fixed-size behaviour unchanged.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    `causal_bias_slope`: soft-causal ablation (see causal_velocity_field.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    causal_bias). Only meaningful with causal=False -- it grades the\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    movable-to-movable penalty instead of leaving it at zero. 0.0 (default)\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    is a no-op, byte-for-byte the pre-existing behaviour.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    \u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","    rank, selected = selected_ranks(rank, available)","    g_t = torch.where(selected[..., \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e], g_t, torch.zeros_like(g_t))","    b, n, _ = static.shape","    te = time_embedding(t, time_dim)[:, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e].expand(b, n, time_dim)","    obj = cfg_in(torch.cat([static, g_t, te], dim=-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e))","    \u003cspan class=\"tok-comment\"\u003e# A rank restriction applies to generated decisions, never to currently\u003c/span\u003e","    \u003cspan class=\"tok-comment\"\u003e# observed geometry. Separate read-only copies expose ALL observed objects,\u003c/span\u003e","    \u003cspan class=\"tok-comment\"\u003e# including selected objects whose generated targets must remain hidden.\u003c/span\u003e","    observed = cfg_in(torch.cat([static, torch.zeros_like(g_t), te], dim=-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e))","    tokens = torch.cat([context, obj, scene, observed], dim=\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e)","    mask = causal_mask(rank, selected, scene.shape[\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e] + n, causal=causal)","    bias = (causal_bias(rank, selected, scene.shape[\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e] + n, causal_bias_slope)","            \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e causal_bias_slope \u003cspan class=\"tok-keyword\"\u003eelse\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e)","    \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e key_mask \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e:","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e key_mask.shape != mask.shape[:\u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e]:","            \u003cspan class=\"tok-keyword\"\u003eraise\u003c/span\u003e ValueError(\u003cspan class=\"tok-string\"\u003e\u0026quot;key_mask must cover context, objects, scene and observed copies\u0026quot;\u003c/span\u003e)","        mask = mask | ~key_mask[:, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e, :]","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e head(trunk(tokens, mask=mask, bias=bias)[:, \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e:\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e + n])","","","\u003cspan class=\"tok-keyword\"\u003eclass\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003eRankCausalTargetFlow\u003c/span\u003e(nn.Module):","    \u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003e__init__\u003c/span\u003e(\u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e, dim, target_dim, depth=\u003cspan class=\"tok-number\"\u003e4\u003c/span\u003e, heads=\u003cspan class=\"tok-number\"\u003e4\u003c/span\u003e, dim_head=\u003cspan class=\"tok-number\"\u003e32\u003c/span\u003e, causal=\u003cspan class=\"tok-keyword\"\u003eTrue\u003c/span\u003e,","                 causal_bias_slope=\u003cspan class=\"tok-number\"\u003e0.0\u003c/span\u003e):","        super().__init__()","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e dim % \u003cspan class=\"tok-number\"\u003e4\u003c/span\u003e:","            \u003cspan class=\"tok-keyword\"\u003eraise\u003c/span\u003e ValueError(\u003cspan class=\"tok-string\"\u003e\u0026quot;target flow dim must be divisible by 4\u0026quot;\u003c/span\u003e)","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.dim, \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.target_dim, \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.causal = dim, target_dim, causal","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.noise_std = \u003cspan class=\"tok-number\"\u003e1.0\u003c/span\u003e","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.causal_bias_slope = float(causal_bias_slope)  \u003cspan class=\"tok-comment\"\u003e# soft-causal ablation, see causal_velocity_field.causal_bias\u003c/span\u003e","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.cfg_in = nn.Sequential(nn.Linear(dim + target_dim + dim // \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, dim),","                                    nn.GELU(), nn.Linear(dim, dim))","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.trunk = AffordanceTransformer(dim, depth=depth, heads=heads, dim_head=dim_head)","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.head = nn.Sequential(nn.LayerNorm(dim), nn.Linear(dim, dim), nn.GELU(),","                                  nn.Linear(dim, target_dim))","","    \u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003eforward\u003c/span\u003e(\u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e, static, context, scene, g_t, t, rank, selected, key_mask=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e):","        \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e target_velocity(static, context, scene, g_t, t, rank, selected,","                               \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.cfg_in, \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.trunk, \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.head, \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.dim // \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.causal,","                               key_mask=key_mask, causal_bias_slope=\u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.causal_bias_slope)","","    @torch.no_grad()","    \u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003esample\u003c/span\u003e(\u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e, static, context, scene, rank, selected, n_steps=\u003cspan class=\"tok-number\"\u003e30\u003c/span\u003e, generator=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e,","               key_mask=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e, trace=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e):","        \u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;`trace`, if a list, receives (t, state) at every Euler step and at t=1.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        The states are the generator\u0026#x27;s own intermediates. They exist so a figure\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        can show the flow evolving instead of an interpolation of its endpoint;\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        nothing in the planner reads them and the default path is unchanged.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        \u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e n_steps \u0026lt;= \u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e:","            \u003cspan class=\"tok-keyword\"\u003eraise\u003c/span\u003e ValueError(\u003cspan class=\"tok-string\"\u003e\u0026quot;n_steps must be positive\u0026quot;\u003c/span\u003e)","        rank, selected = selected_ranks(rank, selected)","        g = torch.randn(*static.shape[:\u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e], \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.target_dim, device=static.device,","                        dtype=static.dtype, generator=generator) * \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.noise_std","        g = torch.where(selected[..., \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e], g, torch.zeros_like(g))","        \u003cspan class=\"tok-keyword\"\u003efor\u003c/span\u003e k \u003cspan class=\"tok-keyword\"\u003ein\u003c/span\u003e range(n_steps):","            t = torch.full((static.shape[\u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e],), k / n_steps, device=static.device, dtype=static.dtype)","            \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e trace \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e:","                trace.append((k / n_steps, g.detach().clone()))","            v = \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e(static, context, scene, g, t, rank, selected, key_mask=key_mask)","            g = g + torch.where(selected[..., \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e], v, torch.zeros_like(v)) / n_steps","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e trace \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e:","            trace.append((\u003cspan class=\"tok-number\"\u003e1.0\u003c/span\u003e, g.detach().clone()))","        \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e g"],"formatted":{"text":"\"\"\"causalflownet: causal_velocity_field, target_flow.\n\ncausal_velocity_field: Causal velocity field (Stage B): tau-ordered attention -\u003e path velocity.\n\nOnce the priority head has committed an ordering, object i may read only\nobjects that move at-or-before its own turn; the embodiment token, scene\ntokens and immovable objects are static context readable by everyone. The\nhead regresses velocity in each object's OWN path time, so the regression\ntarget is schedule-independent (vanilla conditional flow matching).\n\nThe mask rule that matters (learned the hard way, kept as a gradient test):\ncontext tokens may NOT read movable objects. If they could, a later object's\npose would reach an earlier object through a 2-hop path -- late object -\u003e\ncontext token at layer L -\u003e early object at layer L+1.\n\nein notation:\n  b - batch\n  n - objects\n  t - tokens (1 capability + n objects + s scene)\n\ntarget_flow: CLEAR's task-independent selected-object, order-conditioned target flow.\n\nFlow time is generative time, not controller execution time. Static observations\nare available at every rank; later generated targets are not. Domain adapters\nprovide object/context tokens and interpret/project the final configuration code.\n\"\"\"\n\n# ---- causal_velocity_field ----\nimport torch\nfrom torch import nn\nfrom torch.nn import Module\n\nfrom clear.model.affordancenet import AffordanceTransformer\nfrom clear.model.encoders import CapabilityEncoder\nfrom clear.model.encoders import SCENE_CHANS, SceneEncoder, obj_feat_dim\nfrom clear.util import wall_oob_penalty\n\nfrom clear.model.affordancenet import StageBAuxHeads\n\n# causal mask\n\n\ndef causal_mask(rank, movable, n_scene, causal=True):\n    \"\"\"(b, t, t) bool, True = blocked.\n\n    A movable object key may be read ONLY by a movable object query with an\n    equal-or-later rank. Every other token may read anything EXCEPT movable\n    objects (the 2-hop rule above).\n\n    causal=False = OBSERVATION-CONSISTENT attention (2026-08-26, adopted after\n    experiments/ordering_ablation: abstract plan success 0.30 -\u003e 0.86 at k=3,\n    physical nocausal_s0 0.920 vs 0.884, PLAN sect95/97): every movable object\n    reads every movable object regardless of rank. This is not a leak of future\n    information: under the slot schedule (util.schedule.oracle_progress) a\n    later-ranked object sits at its current pose x0 while an earlier one moves,\n    i.e. exactly what the robot observes at that moment; earlier-ranked objects\n    are read at their parked pose, which is what the robot will observe once they\n    have been executed. clear.PAMO.forward asserts that invariant\n    (_assert_observation_consistent). The context rule (cap/scene/immovable\n    tokens never read movable objects) is kept as is. causal=True is the legacy\n    rank-causal mask, kept for the ablation and for older checkpoints.\n    \"\"\"\n    b, n = rank.shape\n    t = 1 + n + n_scene\n    mask = torch.zeros(b, t, t, dtype=torch.bool, device=rank.device)\n\n    key_is_movable = torch.zeros(b, t, dtype=torch.bool, device=rank.device)\n    key_is_movable[:, 1 : 1 + n] = movable\n    mask |= key_is_movable[:, None, :]\n\n    allowed = movable[:, :, None] \u0026 movable[:, None, :]\n    if causal:\n        key_is_later = rank[:, None, :] \u003e rank[:, :, None]\n        allowed = allowed \u0026 ~key_is_later\n    mask[:, 1 : 1 + n, 1 : 1 + n] \u0026= ~allowed\n    return mask\n\n\ndef causal_bias(rank, movable, n_scene, slope):\n    \"\"\"(b, t, t) float, additive attention-logit penalty for the SOFT causal\n    variant (2026-09-12): rather than hard-blocking a later-ranked movable\n    key (causal=True) or leaving it fully open (causal=False, the existing\n    no_causal_mask ablation, checked in RESULTS.md and NOT found necessary --\n    held-out CI [-1.83, +4.92]), grade the penalty by how much later it is.\n    slope=0 reduces to causal=False exactly; used with causal=False so the\n    2-hop context rule (context tokens never read movable objects) stays the\n    one hard invariant causal_mask always enforces. Caller passes the SAME\n    `rank`/`movable` (selected) tensors given to causal_mask(..., causal=False).\n    \"\"\"\n    b, n = rank.shape\n    t = 1 + n + n_scene\n    bias = rank.new_zeros(b, t, t, dtype=torch.float32)\n    allowed = movable[:, :, None] \u0026 movable[:, None, :]\n    rank_gap = (rank[:, None, :] - rank[:, :, None]).clamp(min=0).to(torch.float32)\n    bias[:, 1 : 1 + n, 1 : 1 + n] = torch.where(\n        allowed, -slope * rank_gap, torch.zeros_like(rank_gap)\n    )\n    return bias\n\n\n# causal velocity field\n\n\nclass CausalVelocityField(StageBAuxHeads, Module):\n    def __init__(\n        self,\n        grid_hw=(8, 8),\n        dim=128,\n        depth=4,\n        heads=4,\n        dim_head=32,\n        drop_obj=(),\n        obj_extra_dim=0,\n        predict_robot_path=False,\n        condition_smoothness=False,\n        include_reachable=False,\n        predict_feasibility=False,\n        predict_affordance=False,\n        causal=True,\n        capability_encoder=None,\n        scene_channels=SCENE_CHANS,\n    ):\n        super().__init__()\n        self.causal = causal  # False = no_causal_mask ablation, see causal_mask()\n        self.to_object_tokens = nn.Linear(\n            obj_feat_dim(drop_obj, include_reachable) + obj_extra_dim, dim\n        )\n        # capability_encoder: optional module replacing the default vector\n        # encoder (e.g. kappa_set_encoder.KappaSetEncoder); must map its own\n        # `capability` input to a (b, 1, dim) token.\n        self.capability_encoder = (\n            capability_encoder\n            if capability_encoder is not None\n            else CapabilityEncoder(dim)\n        )\n        self.scene_encoder = SceneEncoder(dim, grid_hw, channels=scene_channels)\n        # OPT-IN, same contract as predict_robot_path below: condition_smoothness=False\n        # (the default) leaves this class byte-for-byte the old CausalVelocityField --\n        # no extra params, forward()'s signature accepts `smoothness` but ignores it.\n        # When on, a scalar in [0, 1] biases the capability token via a small additive\n        # projection (not a new token -- inserting one would shift every index the\n        # causal mask and the `tokens[:, 1:1+n]` slicing below already hardcode).\n        # `clear/data/data.py`'s `collate(..., smoothness=True)` supplies the matching\n        # TRAINING label: pose/v_target blended toward a Chaikin-smoothed path by the\n        # same scalar, so the network learns what \"more smoothness\" should look like\n        # rather than only being told to reproduce it post-hoc (see\n        # PAMO.sample_robot_path's own, unrelated, post-hoc EMA `smoothness` param --\n        # deliberately named `smoothness_cond` everywhere in this class to not collide).\n        self.condition_smoothness = condition_smoothness\n        if condition_smoothness:\n            self.smoothness_to_bias = nn.Linear(1, dim)\n        self.transformer = AffordanceTransformer(\n            dim, depth=depth, heads=heads, dim_head=dim_head\n        )\n        self.to_velocity = nn.Sequential(\n            nn.Linear(dim, dim),\n            nn.GELU(),\n            nn.Linear(dim, 3),\n        )\n        # Second head off the same trunk: where does this object END UP,\n        # globally (x1 - current pose) -- not just its local path velocity.\n        # flow_loss alone only ever sees the next instant; this is the signal\n        # that lets training penalize an invalid *resulting* world (see\n        # util/validity.py), which the velocity head has no way to express.\n        self.to_endpoint = nn.Sequential(\n            nn.Linear(dim, dim),\n            nn.GELU(),\n            nn.Linear(dim, 3),\n        )\n\n        # Third pair of heads, OPT-IN (predict_robot_path=False leaves this\n        # class byte-for-byte the old CausalVelocityField -- both existing\n        # call sites in clear.py unpack exactly 2 return values and must not\n        # break). Reads the SAME per-object transformer output as\n        # to_velocity/to_endpoint -- no new token, no rank/mask change, so\n        # none of the causal-mask correctness work above is touched. The\n        # physical quantity is different (the ROBOT's own path to reach this\n        # object, not the object's own placement) but the object's token\n        # already carries everything the mask says it may see (earlier-turn\n        # objects' outcomes, capability, scene) -- see module docstring in\n        # clear/data/waypoint_data.py for what supplies the training label\n        # (Roadmap.path_points, not this repo's grid cell_path -- that labels\n        # OBJECT motion, this labels ROBOT motion, a different quantity that\n        # happens to reuse the same pose/velocity CFM parameterisation).\n        #\n        # Robot position between phases is approximated as the causally\n        # PREVIOUS object's own endpoint (where the robot just finished\n        # pushing it to) -- or the scene's start pose for the first-ranked\n        # object. This needs no new input signal (rank + x1 already exist in\n        # the sequence); it is an approximation, not measured, and is the\n        # first thing to revisit if predicted robot paths look wrong at a\n        # phase boundary. See experiments/e4/HANDOFF_sumo_executor.md\n        # \"\uc2a4\ubb3c\uc77c\uacf1 \ubc88\uc9f8 \ud6c4\uc18d\".\n        self.predict_robot_path = predict_robot_path\n        if predict_robot_path:\n            self.to_robot_velocity = nn.Sequential(\n                nn.Linear(dim, dim), nn.GELU(), nn.Linear(dim, 3)\n            )\n            self.to_robot_endpoint = nn.Sequential(\n                nn.Linear(dim, dim), nn.GELU(), nn.Linear(dim, 3)\n            )\n\n        # Fourth head, OPT-IN (predict_feasibility=False leaves this class\n        # byte-for-byte the old CausalVelocityField, same contract as\n        # predict_robot_path/condition_smoothness above -- forward()'s\n        # existing 2-value return is untouched, only forward_with_feasibility\n        # below uses this). 2026-08-23, PLAN doc S54-62 / experiments/\n        # stageb_clearance_signal/RESULTS.md sect9-10: an RL reward built\n        # from the SAME validated signal (order_index/push_distance/n_movers/\n        # wall-occupancy, sect4-6's v4/v5 feature set) made real placement\n        # accuracy WORSE, not better (miss rate 17.2% -\u003e 41.6%, sect9) --\n        # consistent overoptimization of an imperfect frozen critic via\n        # noisy policy gradient. This head instead trains the SAME kind of\n        # signal via ordinary supervised backprop, directly into the shared\n        # trunk, alongside flow_loss/endpoint_loss -- no policy-gradient\n        # variance, no frozen numpy critic to game. Takes the trunk's own\n        # per-object hidden state PLUS 4 scalars the trunk alone cannot see\n        # (they depend on the CANDIDATE endpoint this same forward pass just\n        # produced, not just the pre-placement context the trunk attends\n        # over): push_distance (from endpoint_delta, literally free --\n        # already computed for endpoint_loss), wall_occ (reuses\n        # wall_oob_penalty's own differentiable bilinear sample, not a new\n        # geometry channel), order_index/n_movers (from `rank`/`movable`,\n        # already in every batch -- v4/v5's single strongest and third-\n        # strongest univariate features, sect6, never before given to any\n        # head as an explicit input). Outputs a per-object SUCCESS LOGIT,\n        # trained with BCEWithLogitsLoss against real physical phase-level\n        # outcomes (the same ~3-4k-row corpus feasibility_critic.py already\n        # builds) -- see clear.py's feasibility_forward for the loss, only\n        # meaningful on batches carrying real labels (see\n        # data/real_corpus.py's build_feasibility_batches).\n        self.predict_feasibility = predict_feasibility\n        if predict_feasibility:\n            self.to_feasibility = nn.Sequential(\n                nn.Linear(dim + 4, dim), nn.GELU(), nn.Linear(dim, 1)\n            )\n            # Residual refinement head (2026-08-23, PLAN doc S54-62 sect16 --\n            # experiments/stageb_clearance_signal/RESULTS.md): the actual\n            # CE-Adapter/CrossTracer mechanism (T_e = T_init + Delta_e), which\n            # sect10's feasibility head alone did NOT implement -- confirmed\n            # directly by reading PAMO.sample()'s own ODE loop: it integrates\n            # `velocity` only and DISCARDS endpoint_delta entirely (`_` in\n            # `velocity, _ = self.velocity_field(...)`), so nothing built in\n            # sect10 could ever have reached actual sampled behavior except\n            # indirectly, through gradient shared with the trunk that also\n            # produces `velocity` -- a real, but diffuse and unconstrained,\n            # coupling, consistent with sect12/15's small, seed-noisy effect.\n            # Same `feas_in` input as to_feasibility (same 4 context scalars\n            # + trunk state); output is a BOUNDED xy correction (delta_max,\n            # tanh-squashed -- CrossTracer's own bounding, and this\n            # project's own S54-62 audit (sect8) already found an unbounded\n            # correction path is exactly how a reward gets gamed).\n            self.delta_max = (\n                1.5  # grid cells -- generously covers sect6's push_distance\n            )\n            # dose-response finding (the \"sweet spot\" sat around 2 cells, the cliff past ~4;\n            # 1.5 lets the residual meaningfully relocate a placement without being able to\n            # single-handedly walk it out to the danger zone sect6 found)\n            self.to_residual = nn.Sequential(\n                nn.Linear(dim + 4, dim), nn.GELU(), nn.Linear(dim, 2)\n            )\n\n        # Fifth head pair, OPT-IN (predict_affordance=False leaves this class\n        # byte-for-byte the old one, same contract as every flag above).\n        # 2026-08-24, RESULTS.md sect22-23: embodiment-conditioned AFFORDANCE\n        # MAP -- per-object (h, w) logits over park cells, supervised by\n        # clear/data/affordance.py's dense oracle labels (oracle.park_valid,\n        # 12 maps/scene, unlimited volume -- the label starvation that sank\n        # sect10-22's per-object-scalar heads does not apply). Standalone\n        # Phase-1 net already cleared the pre-stated gates (held-out per-cell\n        # AUC 0.988, every embodiment \u003e= 0.984 -- train_affordance.py); this\n        # head asks whether the SAME signal can flow through PAMO's own\n        # trunk. Mechanism: object token (query) x scene token (key) dot\n        # product -\u003e coarse (4,4) map in the scene encoder's own token\n        # layout, bilinearly upsampled and refined by a small conv decoder\n        # that re-reads the raw class grid (full-res wall structure the 16\n        # coarse tokens can't carry). The causal mask already lets every\n        # object token read every scene token, and scene tokens never read\n        # movable objects -- so the affordance query is object-conditioned\n        # while the keys stay object-independent, and NOTHING about the mask\n        # changes.\n        self.predict_affordance = predict_affordance\n        if predict_affordance:\n            self.to_afford_q = nn.Linear(dim, dim)\n            self.to_afford_k = nn.Linear(dim, dim)\n            self.afford_decoder = nn.Sequential(\n                nn.Conv2d(1 + 5, dim // 2, 3, padding=1),\n                nn.GELU(),\n                nn.Conv2d(dim // 2, dim // 2, 3, padding=1),\n                nn.GELU(),\n                nn.Conv2d(dim // 2, 1, 1),\n            )\n\n    def forward(\n        self,\n        grid,\n        object_features,\n        capability,\n        rank,\n        movable,\n        context=None,\n        smoothness_cond=None,\n    ):\n        \"\"\"-\u003e (velocity, endpoint_delta), each (b, n, 3). velocity is in each\n        object's own path time; endpoint_delta estimates x1 - pose (used only\n        as an auxiliary training signal -- sample() ignores it, the rollout\n        is still pure CFM integration).\n\n        `context`: see PriorityHead.forward. The mask reads the scene-token\n        count off the tensor rather than off self.scene_encoder, so a front end\n        with a different token count cannot silently mis-mask.\n\n        `smoothness_cond`: (b,) in [0, 1], only read when condition_smoothness=True\n        (required then -- see __init__).\n        \"\"\"\n        out = self._trunk_out(\n            grid, object_features, capability, rank, movable, context, smoothness_cond\n        )\n        return self.to_velocity(out), self.to_endpoint(out)\n\n    def _trunk_out(\n        self,\n        grid,\n        object_features,\n        capability,\n        rank,\n        movable,\n        context=None,\n        smoothness_cond=None,\n    ):\n        full, n = self._trunk_full(\n            grid, object_features, capability, rank, movable, context, smoothness_cond\n        )\n        return full[:, 1 : 1 + n]\n\n    def _trunk_full(\n        self,\n        grid,\n        object_features,\n        capability,\n        rank,\n        movable,\n        context=None,\n        smoothness_cond=None,\n    ):\n        \"\"\"-\u003e (all transformer token outputs (b, 1+n+s, d), n). _trunk_out is\n        the [1:1+n] object slice of this -- one shared implementation so the\n        affordance head's scene-token reads can never drift from what the\n        object heads were computed with.\"\"\"\n        objects = self.to_object_tokens(object_features)\n        cap_token, scene_tokens = (\n            context\n            if context is not None\n            else (self.capability_encoder(capability), self.scene_encoder(grid))\n        )\n        if self.condition_smoothness:\n            assert (\n                smoothness_cond is not None\n            ), \"condition_smoothness=True requires smoothness_cond\"\n            cap_token = (\n                cap_token\n                + self.smoothness_to_bias(smoothness_cond.view(-1, 1))[:, None, :]\n            )\n        tokens = torch.cat([cap_token, objects, scene_tokens], dim=1)\n\n        mask = causal_mask(rank, movable, scene_tokens.shape[1], causal=self.causal)\n        return self.transformer(tokens, mask=mask), objects.shape[1]\n\n    # forward_with_{robot_path,feasibility,affordance} live in stageb_aux_heads.py (mixin)\n\n\ndef _self_check():\n    import torch\n\n    from clear.data.capability import FEATURE_DIM\n    from clear.model.encoders import obj_feat_dim\n\n    torch.manual_seed(0)\n    b, n, dim = 2, 4, 32\n    grid = torch.zeros(b, 5, 8, 8)\n    object_features = torch.randn(b, n, obj_feat_dim(()))\n    capability = torch.randn(b, FEATURE_DIM)\n    rank = torch.stack([torch.randperm(n) for _ in range(b)])\n    movable = torch.ones(b, n, dtype=torch.bool)\n\n    # predict_robot_path=False (the default, and what PAMO/MazePAMO's existing\n    # 2 call sites unpack) must be byte-for-byte the pre-extension class.\n    plain = CausalVelocityField(grid_hw=(8, 8), dim=dim, depth=2, heads=2, dim_head=16)\n    assert not hasattr(\n        plain, \"to_robot_velocity\"\n    ), \"default field must not carry robot heads at all\"\n    v, e = plain.forward(grid, object_features, capability, rank, movable)\n    assert v.shape == (b, n, 3) and e.shape == (b, n, 3)\n    print(\"ok predict_robot_path=False: no robot heads, forward() shape unchanged\")\n\n    reachable_feats = torch.randn(b, n, obj_feat_dim((), include_reachable=True))\n    with_reachable = CausalVelocityField(\n        grid_hw=(8, 8), dim=dim, depth=2, heads=2, dim_head=16, include_reachable=True\n    )\n    v, e = with_reachable.forward(grid, reachable_feats, capability, rank, movable)\n    assert v.shape == (b, n, 3) and e.shape == (b, n, 3)\n    print(\"ok include_reachable=True: to_object_tokens sized for the extra column\")\n\n    vf = CausalVelocityField(\n        grid_hw=(8, 8), dim=dim, depth=2, heads=2, dim_head=16, predict_robot_path=True\n    )\n    v2, e2, rv, re = vf.forward_with_robot_path(\n        grid, object_features, capability, rank, movable\n    )\n    assert rv.shape == (b, n, 3) and re.shape == (b, n, 3)\n    assert torch.isfinite(rv).all() and torch.isfinite(re).all()\n    v3, e3 = vf.forward(grid, object_features, capability, rank, movable)\n    assert torch.allclose(v2, v3) and torch.allclose(\n        e2, e3\n    ), \"forward() and forward_with_robot_path() must share the identical trunk output\"\n    print(\n        \"ok predict_robot_path=True: robot heads present, shared trunk output matches forward()\"\n    )\n\n    (rv.sum() + re.sum()).backward()\n    print(\"ok gradients reach the robot-path heads\")\n\n    # condition_smoothness=False (default) must stay byte-for-byte identical too,\n    # and =True must actually change the output when the scalar changes.\n    assert not hasattr(\n        plain, \"smoothness_to_bias\"\n    ), \"default field must not carry the smoothness bias at all\"\n    sv = CausalVelocityField(\n        grid_hw=(8, 8),\n        dim=dim,\n        depth=2,\n        heads=2,\n        dim_head=16,\n        condition_smoothness=True,\n    )\n    lo = torch.zeros(b)\n    hi = torch.ones(b)\n    v_lo, _ = sv.forward(\n        grid, object_features, capability, rank, movable, smoothness_cond=lo\n    )\n    v_hi, _ = sv.forward(\n        grid, object_features, capability, rank, movable, smoothness_cond=hi\n    )\n    assert not torch.allclose(\n        v_lo, v_hi\n    ), \"smoothness_cond=0 vs 1 produced identical output\"\n    try:\n        sv.forward(grid, object_features, capability, rank, movable)\n        raise AssertionError(\n            \"condition_smoothness=True must require smoothness_cond, not silently default it\"\n        )\n    except AssertionError as e:\n        if \"requires smoothness_cond\" not in str(e):\n            raise\n    print(\n        \"ok condition_smoothness=True: output actually depends on the scalar, and is required\"\n    )\n\n\n# ---- target_flow ----\nimport math\n\n\ndef selection_mask(logits, available):\n    return available \u0026 (logits \u003e 0)\n\n\ndef priority_scale(raw, minimum=0.05, maximum=0.5):\n    \"\"\"Smooth bounded Gaussian scale; no hard-clamp dead zone.\"\"\"\n    return minimum + (maximum - minimum) * torch.sigmoid(raw)\n\n\ndef selected_ranks(rank, available):\n    n = rank.shape[-1]\n    selected = available \u0026 (rank \u003e= 0) \u0026 (rank \u003c n)\n    # zeros_like+n rather than full_like(rank, n): identical result, but the NPU\n    # compiler's tvm frontend mishandles full_like with a scalar fill.\n    return torch.where(selected, rank, torch.zeros_like(rank) + n), selected\n\n\ndef rank_selected(priority, selected, limit=None):\n    \"\"\"Ascending sampled priorities; omitted objects use the N sentinel.\"\"\"\n    n = priority.shape[-1]\n    if limit is not None and limit \u003c 0:\n        raise ValueError(\"interaction limit must be nonnegative\")\n    order = priority.masked_fill(~selected, float(\"inf\")).argsort(dim=-1, stable=True)\n    rank = torch.empty_like(order).scatter_(\n        1, order, torch.arange(n, device=order.device).expand_as(order)\n    )\n    active = selected \u0026 (rank \u003c (n if limit is None else limit))\n    return torch.where(active, rank, torch.full_like(rank, n)), active\n\n\ndef time_embedding(t, dim):\n    half = dim // 2\n    freqs = torch.exp(\n        -math.log(1000.0)\n        * torch.arange(half, device=t.device, dtype=t.dtype)\n        / max(1, half - 1)\n    )\n    a = t[..., None] * freqs\n    return torch.cat([a.sin(), a.cos()], dim=-1)\n\n\ndef target_velocity(\n    static,\n    context,\n    scene,\n    g_t,\n    t,\n    rank,\n    available,\n    cfg_in,\n    trunk,\n    head,\n    time_dim,\n    causal=True,\n    key_mask=None,\n    causal_bias_slope=0.0,\n):\n    \"\"\"Shared Stage B implementation; modules remain owned by each checkpoint.\n\n    `key_mask` (b, 1 + n + s + n) bool marks keys that exist: padded object or\n    scene slots are never read. None keeps the fixed-size behaviour unchanged.\n\n    `causal_bias_slope`: soft-causal ablation (see causal_velocity_field.\n    causal_bias). Only meaningful with causal=False -- it grades the\n    movable-to-movable penalty instead of leaving it at zero. 0.0 (default)\n    is a no-op, byte-for-byte the pre-existing behaviour.\n    \"\"\"\n    rank, selected = selected_ranks(rank, available)\n    g_t = torch.where(selected[..., None], g_t, torch.zeros_like(g_t))\n    b, n, _ = static.shape\n    te = time_embedding(t, time_dim)[:, None].expand(b, n, time_dim)\n    obj = cfg_in(torch.cat([static, g_t, te], dim=-1))\n    # A rank restriction applies to generated decisions, never to currently\n    # observed geometry. Separate read-only copies expose ALL observed objects,\n    # including selected objects whose generated targets must remain hidden.\n    observed = cfg_in(torch.cat([static, torch.zeros_like(g_t), te], dim=-1))\n    tokens = torch.cat([context, obj, scene, observed], dim=1)\n    mask = causal_mask(rank, selected, scene.shape[1] + n, causal=causal)\n    bias = (\n        causal_bias(rank, selected, scene.shape[1] + n, causal_bias_slope)\n        if causal_bias_slope\n        else None\n    )\n    if key_mask is not None:\n        if key_mask.shape != mask.shape[:2]:\n            raise ValueError(\n                \"key_mask must cover context, objects, scene and observed copies\"\n            )\n        mask = mask | ~key_mask[:, None, :]\n    return head(trunk(tokens, mask=mask, bias=bias)[:, 1 : 1 + n])\n\n\nclass RankCausalTargetFlow(nn.Module):\n    def __init__(\n        self,\n        dim,\n        target_dim,\n        depth=4,\n        heads=4,\n        dim_head=32,\n        causal=True,\n        causal_bias_slope=0.0,\n    ):\n        super().__init__()\n        if dim % 4:\n            raise ValueError(\"target flow dim must be divisible by 4\")\n        self.dim, self.target_dim, self.causal = dim, target_dim, causal\n        self.noise_std = 1.0\n        self.causal_bias_slope = float(\n            causal_bias_slope\n        )  # soft-causal ablation, see causal_velocity_field.causal_bias\n        self.cfg_in = nn.Sequential(\n            nn.Linear(dim + target_dim + dim // 2, dim), nn.GELU(), nn.Linear(dim, dim)\n        )\n        self.trunk = AffordanceTransformer(\n            dim, depth=depth, heads=heads, dim_head=dim_head\n        )\n        self.head = nn.Sequential(\n            nn.LayerNorm(dim),\n            nn.Linear(dim, dim),\n            nn.GELU(),\n            nn.Linear(dim, target_dim),\n        )\n\n    def forward(self, static, context, scene, g_t, t, rank, selected, key_mask=None):\n        return target_velocity(\n            static,\n            context,\n            scene,\n            g_t,\n            t,\n            rank,\n            selected,\n            self.cfg_in,\n            self.trunk,\n            self.head,\n            self.dim // 2,\n            self.causal,\n            key_mask=key_mask,\n            causal_bias_slope=self.causal_bias_slope,\n        )\n\n    @torch.no_grad()\n    def sample(\n        self,\n        static,\n        context,\n        scene,\n        rank,\n        selected,\n        n_steps=30,\n        generator=None,\n        key_mask=None,\n        trace=None,\n    ):\n        \"\"\"`trace`, if a list, receives (t, state) at every Euler step and at t=1.\n\n        The states are the generator's own intermediates. They exist so a figure\n        can show the flow evolving instead of an interpolation of its endpoint;\n        nothing in the planner reads them and the default path is unchanged.\n        \"\"\"\n        if n_steps \u003c= 0:\n            raise ValueError(\"n_steps must be positive\")\n        rank, selected = selected_ranks(rank, selected)\n        g = (\n            torch.randn(\n                *static.shape[:2],\n                self.target_dim,\n                device=static.device,\n                dtype=static.dtype,\n                generator=generator\n            )\n            * self.noise_std\n        )\n        g = torch.where(selected[..., None], g, torch.zeros_like(g))\n        for k in range(n_steps):\n            t = torch.full(\n                (static.shape[0],),\n                k / n_steps,\n                device=static.device,\n                dtype=static.dtype,\n            )\n            if trace is not None:\n                trace.append((k / n_steps, g.detach().clone()))\n            v = self(static, context, scene, g, t, rank, selected, key_mask=key_mask)\n            g = g + torch.where(selected[..., None], v, torch.zeros_like(v)) / n_steps\n        if trace is not None:\n            trace.append((1.0, g.detach().clone()))\n        return g\n","lines":["\u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;causalflownet: causal_velocity_field, target_flow.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003ecausal_velocity_field: Causal velocity field (Stage B): tau-ordered attention -\u0026gt; path velocity.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003eOnce the priority head has committed an ordering, object i may read only\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003eobjects that move at-or-before its own turn; the embodiment token, scene\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003etokens and immovable objects are static context readable by everyone. The\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003ehead regresses velocity in each object\u0026#x27;s OWN path time, so the regression\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003etarget is schedule-independent (vanilla conditional flow matching).\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003eThe mask rule that matters (learned the hard way, kept as a gradient test):\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003econtext tokens may NOT read movable objects. If they could, a later object\u0026#x27;s\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003epose would reach an earlier object through a 2-hop path -- late object -\u0026gt;\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003econtext token at layer L -\u0026gt; early object at layer L+1.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003eein notation:\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e  b - batch\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e  n - objects\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e  t - tokens (1 capability + n objects + s scene)\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003etarget_flow: CLEAR\u0026#x27;s task-independent selected-object, order-conditioned target flow.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003eFlow time is generative time, not controller execution time. Static observations\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003eare available at every rank; later generated targets are not. Domain adapters\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003eprovide object/context tokens and interpret/project the final configuration code.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","","\u003cspan class=\"tok-comment\"\u003e# ---- causal_velocity_field ----\u003c/span\u003e","\u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e torch","\u003cspan class=\"tok-keyword\"\u003efrom\u003c/span\u003e torch \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e nn","\u003cspan class=\"tok-keyword\"\u003efrom\u003c/span\u003e torch.nn \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e Module","","\u003cspan class=\"tok-keyword\"\u003efrom\u003c/span\u003e clear.model.affordancenet \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e AffordanceTransformer","\u003cspan class=\"tok-keyword\"\u003efrom\u003c/span\u003e clear.model.encoders \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e CapabilityEncoder","\u003cspan class=\"tok-keyword\"\u003efrom\u003c/span\u003e clear.model.encoders \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e SCENE_CHANS, SceneEncoder, obj_feat_dim","\u003cspan class=\"tok-keyword\"\u003efrom\u003c/span\u003e clear.util \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e wall_oob_penalty","","\u003cspan class=\"tok-keyword\"\u003efrom\u003c/span\u003e clear.model.affordancenet \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e StageBAuxHeads","","\u003cspan class=\"tok-comment\"\u003e# causal mask\u003c/span\u003e","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003ecausal_mask\u003c/span\u003e(rank, movable, n_scene, causal=\u003cspan class=\"tok-keyword\"\u003eTrue\u003c/span\u003e):","    \u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;(b, t, t) bool, True = blocked.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    A movable object key may be read ONLY by a movable object query with an\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    equal-or-later rank. Every other token may read anything EXCEPT movable\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    objects (the 2-hop rule above).\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    causal=False = OBSERVATION-CONSISTENT attention (2026-08-26, adopted after\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    experiments/ordering_ablation: abstract plan success 0.30 -\u0026gt; 0.86 at k=3,\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    physical nocausal_s0 0.920 vs 0.884, PLAN sect95/97): every movable object\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    reads every movable object regardless of rank. This is not a leak of future\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    information: under the slot schedule (util.schedule.oracle_progress) a\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    later-ranked object sits at its current pose x0 while an earlier one moves,\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    i.e. exactly what the robot observes at that moment; earlier-ranked objects\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    are read at their parked pose, which is what the robot will observe once they\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    have been executed. clear.PAMO.forward asserts that invariant\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    (_assert_observation_consistent). The context rule (cap/scene/immovable\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    tokens never read movable objects) is kept as is. causal=True is the legacy\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    rank-causal mask, kept for the ablation and for older checkpoints.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    \u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","    b, n = rank.shape","    t = \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e + n + n_scene","    mask = torch.zeros(b, t, t, dtype=torch.bool, device=rank.device)","","    key_is_movable = torch.zeros(b, t, dtype=torch.bool, device=rank.device)","    key_is_movable[:, \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e : \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e + n] = movable","    mask |= key_is_movable[:, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e, :]","","    allowed = movable[:, :, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e] \u0026amp; movable[:, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e, :]","    \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e causal:","        key_is_later = rank[:, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e, :] \u0026gt; rank[:, :, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e]","        allowed = allowed \u0026amp; ~key_is_later","    mask[:, \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e : \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e + n, \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e : \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e + n] \u0026amp;= ~allowed","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e mask","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003ecausal_bias\u003c/span\u003e(rank, movable, n_scene, slope):","    \u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;(b, t, t) float, additive attention-logit penalty for the SOFT causal\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    variant (2026-09-12): rather than hard-blocking a later-ranked movable\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    key (causal=True) or leaving it fully open (causal=False, the existing\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    no_causal_mask ablation, checked in RESULTS.md and NOT found necessary --\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    held-out CI [-1.83, +4.92]), grade the penalty by how much later it is.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    slope=0 reduces to causal=False exactly; used with causal=False so the\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    2-hop context rule (context tokens never read movable objects) stays the\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    one hard invariant causal_mask always enforces. Caller passes the SAME\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    `rank`/`movable` (selected) tensors given to causal_mask(..., causal=False).\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    \u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","    b, n = rank.shape","    t = \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e + n + n_scene","    bias = rank.new_zeros(b, t, t, dtype=torch.float32)","    allowed = movable[:, :, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e] \u0026amp; movable[:, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e, :]","    rank_gap = (rank[:, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e, :] - rank[:, :, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e]).clamp(min=\u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e).to(torch.float32)","    bias[:, \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e : \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e + n, \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e : \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e + n] = torch.where(","        allowed, -slope * rank_gap, torch.zeros_like(rank_gap)","    )","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e bias","","","\u003cspan class=\"tok-comment\"\u003e# causal velocity field\u003c/span\u003e","","","\u003cspan class=\"tok-keyword\"\u003eclass\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003eCausalVelocityField\u003c/span\u003e(StageBAuxHeads, Module):","    \u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003e__init__\u003c/span\u003e(","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e,","        grid_hw=(\u003cspan class=\"tok-number\"\u003e8\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e8\u003c/span\u003e),","        dim=\u003cspan class=\"tok-number\"\u003e128\u003c/span\u003e,","        depth=\u003cspan class=\"tok-number\"\u003e4\u003c/span\u003e,","        heads=\u003cspan class=\"tok-number\"\u003e4\u003c/span\u003e,","        dim_head=\u003cspan class=\"tok-number\"\u003e32\u003c/span\u003e,","        drop_obj=(),","        obj_extra_dim=\u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e,","        predict_robot_path=\u003cspan class=\"tok-keyword\"\u003eFalse\u003c/span\u003e,","        condition_smoothness=\u003cspan class=\"tok-keyword\"\u003eFalse\u003c/span\u003e,","        include_reachable=\u003cspan class=\"tok-keyword\"\u003eFalse\u003c/span\u003e,","        predict_feasibility=\u003cspan class=\"tok-keyword\"\u003eFalse\u003c/span\u003e,","        predict_affordance=\u003cspan class=\"tok-keyword\"\u003eFalse\u003c/span\u003e,","        causal=\u003cspan class=\"tok-keyword\"\u003eTrue\u003c/span\u003e,","        capability_encoder=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e,","        scene_channels=SCENE_CHANS,","    ):","        super().__init__()","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.causal = causal  \u003cspan class=\"tok-comment\"\u003e# False = no_causal_mask ablation, see causal_mask()\u003c/span\u003e","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.to_object_tokens = nn.Linear(","            obj_feat_dim(drop_obj, include_reachable) + obj_extra_dim, dim","        )","        \u003cspan class=\"tok-comment\"\u003e# capability_encoder: optional module replacing the default vector\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# encoder (e.g. kappa_set_encoder.KappaSetEncoder); must map its own\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# `capability` input to a (b, 1, dim) token.\u003c/span\u003e","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.capability_encoder = (","            capability_encoder","            \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e capability_encoder \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e","            \u003cspan class=\"tok-keyword\"\u003eelse\u003c/span\u003e CapabilityEncoder(dim)","        )","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.scene_encoder = SceneEncoder(dim, grid_hw, channels=scene_channels)","        \u003cspan class=\"tok-comment\"\u003e# OPT-IN, same contract as predict_robot_path below: condition_smoothness=False\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# (the default) leaves this class byte-for-byte the old CausalVelocityField --\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# no extra params, forward()\u0026#x27;s signature accepts `smoothness` but ignores it.\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# When on, a scalar in [0, 1] biases the capability token via a small additive\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# projection (not a new token -- inserting one would shift every index the\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# causal mask and the `tokens[:, 1:1+n]` slicing below already hardcode).\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# `clear/data/data.py`\u0026#x27;s `collate(..., smoothness=True)` supplies the matching\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# TRAINING label: pose/v_target blended toward a Chaikin-smoothed path by the\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# same scalar, so the network learns what \u0026quot;more smoothness\u0026quot; should look like\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# rather than only being told to reproduce it post-hoc (see\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# PAMO.sample_robot_path\u0026#x27;s own, unrelated, post-hoc EMA `smoothness` param --\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# deliberately named `smoothness_cond` everywhere in this class to not collide).\u003c/span\u003e","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.condition_smoothness = condition_smoothness","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e condition_smoothness:","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.smoothness_to_bias = nn.Linear(\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e, dim)","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.transformer = AffordanceTransformer(","            dim, depth=depth, heads=heads, dim_head=dim_head","        )","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.to_velocity = nn.Sequential(","            nn.Linear(dim, dim),","            nn.GELU(),","            nn.Linear(dim, \u003cspan class=\"tok-number\"\u003e3\u003c/span\u003e),","        )","        \u003cspan class=\"tok-comment\"\u003e# Second head off the same trunk: where does this object END UP,\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# globally (x1 - current pose) -- not just its local path velocity.\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# flow_loss alone only ever sees the next instant; this is the signal\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# that lets training penalize an invalid *resulting* world (see\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# util/validity.py), which the velocity head has no way to express.\u003c/span\u003e","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.to_endpoint = nn.Sequential(","            nn.Linear(dim, dim),","            nn.GELU(),","            nn.Linear(dim, \u003cspan class=\"tok-number\"\u003e3\u003c/span\u003e),","        )","","        \u003cspan class=\"tok-comment\"\u003e# Third pair of heads, OPT-IN (predict_robot_path=False leaves this\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# class byte-for-byte the old CausalVelocityField -- both existing\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# call sites in clear.py unpack exactly 2 return values and must not\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# break). Reads the SAME per-object transformer output as\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# to_velocity/to_endpoint -- no new token, no rank/mask change, so\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# none of the causal-mask correctness work above is touched. The\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# physical quantity is different (the ROBOT\u0026#x27;s own path to reach this\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# object, not the object\u0026#x27;s own placement) but the object\u0026#x27;s token\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# already carries everything the mask says it may see (earlier-turn\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# objects\u0026#x27; outcomes, capability, scene) -- see module docstring in\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# clear/data/waypoint_data.py for what supplies the training label\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# (Roadmap.path_points, not this repo\u0026#x27;s grid cell_path -- that labels\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# OBJECT motion, this labels ROBOT motion, a different quantity that\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# happens to reuse the same pose/velocity CFM parameterisation).\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e#\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# Robot position between phases is approximated as the causally\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# PREVIOUS object\u0026#x27;s own endpoint (where the robot just finished\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# pushing it to) -- or the scene\u0026#x27;s start pose for the first-ranked\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# object. This needs no new input signal (rank + x1 already exist in\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# the sequence); it is an approximation, not measured, and is the\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# first thing to revisit if predicted robot paths look wrong at a\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# phase boundary. See experiments/e4/HANDOFF_sumo_executor.md\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# \u0026quot;\uc2a4\ubb3c\uc77c\uacf1 \ubc88\uc9f8 \ud6c4\uc18d\u0026quot;.\u003c/span\u003e","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.predict_robot_path = predict_robot_path","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e predict_robot_path:","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.to_robot_velocity = nn.Sequential(","                nn.Linear(dim, dim), nn.GELU(), nn.Linear(dim, \u003cspan class=\"tok-number\"\u003e3\u003c/span\u003e)","            )","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.to_robot_endpoint = nn.Sequential(","                nn.Linear(dim, dim), nn.GELU(), nn.Linear(dim, \u003cspan class=\"tok-number\"\u003e3\u003c/span\u003e)","            )","","        \u003cspan class=\"tok-comment\"\u003e# Fourth head, OPT-IN (predict_feasibility=False leaves this class\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# byte-for-byte the old CausalVelocityField, same contract as\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# predict_robot_path/condition_smoothness above -- forward()\u0026#x27;s\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# existing 2-value return is untouched, only forward_with_feasibility\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# below uses this). 2026-08-23, PLAN doc S54-62 / experiments/\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# stageb_clearance_signal/RESULTS.md sect9-10: an RL reward built\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# from the SAME validated signal (order_index/push_distance/n_movers/\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# wall-occupancy, sect4-6\u0026#x27;s v4/v5 feature set) made real placement\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# accuracy WORSE, not better (miss rate 17.2% -\u0026gt; 41.6%, sect9) --\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# consistent overoptimization of an imperfect frozen critic via\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# noisy policy gradient. This head instead trains the SAME kind of\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# signal via ordinary supervised backprop, directly into the shared\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# trunk, alongside flow_loss/endpoint_loss -- no policy-gradient\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# variance, no frozen numpy critic to game. Takes the trunk\u0026#x27;s own\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# per-object hidden state PLUS 4 scalars the trunk alone cannot see\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# (they depend on the CANDIDATE endpoint this same forward pass just\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# produced, not just the pre-placement context the trunk attends\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# over): push_distance (from endpoint_delta, literally free --\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# already computed for endpoint_loss), wall_occ (reuses\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# wall_oob_penalty\u0026#x27;s own differentiable bilinear sample, not a new\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# geometry channel), order_index/n_movers (from `rank`/`movable`,\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# already in every batch -- v4/v5\u0026#x27;s single strongest and third-\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# strongest univariate features, sect6, never before given to any\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# head as an explicit input). Outputs a per-object SUCCESS LOGIT,\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# trained with BCEWithLogitsLoss against real physical phase-level\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# outcomes (the same ~3-4k-row corpus feasibility_critic.py already\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# builds) -- see clear.py\u0026#x27;s feasibility_forward for the loss, only\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# meaningful on batches carrying real labels (see\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# data/real_corpus.py\u0026#x27;s build_feasibility_batches).\u003c/span\u003e","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.predict_feasibility = predict_feasibility","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e predict_feasibility:","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.to_feasibility = nn.Sequential(","                nn.Linear(dim + \u003cspan class=\"tok-number\"\u003e4\u003c/span\u003e, dim), nn.GELU(), nn.Linear(dim, \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e)","            )","            \u003cspan class=\"tok-comment\"\u003e# Residual refinement head (2026-08-23, PLAN doc S54-62 sect16 --\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# experiments/stageb_clearance_signal/RESULTS.md): the actual\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# CE-Adapter/CrossTracer mechanism (T_e = T_init + Delta_e), which\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# sect10\u0026#x27;s feasibility head alone did NOT implement -- confirmed\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# directly by reading PAMO.sample()\u0026#x27;s own ODE loop: it integrates\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# `velocity` only and DISCARDS endpoint_delta entirely (`_` in\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# `velocity, _ = self.velocity_field(...)`), so nothing built in\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# sect10 could ever have reached actual sampled behavior except\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# indirectly, through gradient shared with the trunk that also\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# produces `velocity` -- a real, but diffuse and unconstrained,\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# coupling, consistent with sect12/15\u0026#x27;s small, seed-noisy effect.\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# Same `feas_in` input as to_feasibility (same 4 context scalars\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# + trunk state); output is a BOUNDED xy correction (delta_max,\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# tanh-squashed -- CrossTracer\u0026#x27;s own bounding, and this\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# project\u0026#x27;s own S54-62 audit (sect8) already found an unbounded\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# correction path is exactly how a reward gets gamed).\u003c/span\u003e","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.delta_max = (","                \u003cspan class=\"tok-number\"\u003e1.5\u003c/span\u003e  \u003cspan class=\"tok-comment\"\u003e# grid cells -- generously covers sect6\u0026#x27;s push_distance\u003c/span\u003e","            )","            \u003cspan class=\"tok-comment\"\u003e# dose-response finding (the \u0026quot;sweet spot\u0026quot; sat around 2 cells, the cliff past ~4;\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# 1.5 lets the residual meaningfully relocate a placement without being able to\u003c/span\u003e","            \u003cspan class=\"tok-comment\"\u003e# single-handedly walk it out to the danger zone sect6 found)\u003c/span\u003e","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.to_residual = nn.Sequential(","                nn.Linear(dim + \u003cspan class=\"tok-number\"\u003e4\u003c/span\u003e, dim), nn.GELU(), nn.Linear(dim, \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e)","            )","","        \u003cspan class=\"tok-comment\"\u003e# Fifth head pair, OPT-IN (predict_affordance=False leaves this class\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# byte-for-byte the old one, same contract as every flag above).\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# 2026-08-24, RESULTS.md sect22-23: embodiment-conditioned AFFORDANCE\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# MAP -- per-object (h, w) logits over park cells, supervised by\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# clear/data/affordance.py\u0026#x27;s dense oracle labels (oracle.park_valid,\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# 12 maps/scene, unlimited volume -- the label starvation that sank\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# sect10-22\u0026#x27;s per-object-scalar heads does not apply). Standalone\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# Phase-1 net already cleared the pre-stated gates (held-out per-cell\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# AUC 0.988, every embodiment \u0026gt;= 0.984 -- train_affordance.py); this\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# head asks whether the SAME signal can flow through PAMO\u0026#x27;s own\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# trunk. Mechanism: object token (query) x scene token (key) dot\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# product -\u0026gt; coarse (4,4) map in the scene encoder\u0026#x27;s own token\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# layout, bilinearly upsampled and refined by a small conv decoder\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# that re-reads the raw class grid (full-res wall structure the 16\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# coarse tokens can\u0026#x27;t carry). The causal mask already lets every\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# object token read every scene token, and scene tokens never read\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# movable objects -- so the affordance query is object-conditioned\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# while the keys stay object-independent, and NOTHING about the mask\u003c/span\u003e","        \u003cspan class=\"tok-comment\"\u003e# changes.\u003c/span\u003e","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.predict_affordance = predict_affordance","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e predict_affordance:","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.to_afford_q = nn.Linear(dim, dim)","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.to_afford_k = nn.Linear(dim, dim)","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.afford_decoder = nn.Sequential(","                nn.Conv2d(\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e + \u003cspan class=\"tok-number\"\u003e5\u003c/span\u003e, dim // \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e3\u003c/span\u003e, padding=\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e),","                nn.GELU(),","                nn.Conv2d(dim // \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, dim // \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e3\u003c/span\u003e, padding=\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e),","                nn.GELU(),","                nn.Conv2d(dim // \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e),","            )","","    \u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003eforward\u003c/span\u003e(","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e,","        grid,","        object_features,","        capability,","        rank,","        movable,","        context=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e,","        smoothness_cond=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e,","    ):","        \u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;-\u0026gt; (velocity, endpoint_delta), each (b, n, 3). velocity is in each\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        object\u0026#x27;s own path time; endpoint_delta estimates x1 - pose (used only\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        as an auxiliary training signal -- sample() ignores it, the rollout\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        is still pure CFM integration).\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        `context`: see PriorityHead.forward. The mask reads the scene-token\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        count off the tensor rather than off self.scene_encoder, so a front end\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        with a different token count cannot silently mis-mask.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        `smoothness_cond`: (b,) in [0, 1], only read when condition_smoothness=True\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        (required then -- see __init__).\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        \u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","        out = \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e._trunk_out(","            grid, object_features, capability, rank, movable, context, smoothness_cond","        )","        \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.to_velocity(out), \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.to_endpoint(out)","","    \u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003e_trunk_out\u003c/span\u003e(","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e,","        grid,","        object_features,","        capability,","        rank,","        movable,","        context=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e,","        smoothness_cond=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e,","    ):","        full, n = \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e._trunk_full(","            grid, object_features, capability, rank, movable, context, smoothness_cond","        )","        \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e full[:, \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e : \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e + n]","","    \u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003e_trunk_full\u003c/span\u003e(","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e,","        grid,","        object_features,","        capability,","        rank,","        movable,","        context=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e,","        smoothness_cond=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e,","    ):","        \u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;-\u0026gt; (all transformer token outputs (b, 1+n+s, d), n). _trunk_out is\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        the [1:1+n] object slice of this -- one shared implementation so the\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        affordance head\u0026#x27;s scene-token reads can never drift from what the\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        object heads were computed with.\u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","        objects = \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.to_object_tokens(object_features)","        cap_token, scene_tokens = (","            context","            \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e context \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e","            \u003cspan class=\"tok-keyword\"\u003eelse\u003c/span\u003e (\u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.capability_encoder(capability), \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.scene_encoder(grid))","        )","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.condition_smoothness:","            \u003cspan class=\"tok-keyword\"\u003eassert\u003c/span\u003e (","                smoothness_cond \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e","            ), \u003cspan class=\"tok-string\"\u003e\u0026quot;condition_smoothness=True requires smoothness_cond\u0026quot;\u003c/span\u003e","            cap_token = (","                cap_token","                + \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.smoothness_to_bias(smoothness_cond.view(-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e))[:, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e, :]","            )","        tokens = torch.cat([cap_token, objects, scene_tokens], dim=\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e)","","        mask = causal_mask(rank, movable, scene_tokens.shape[\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e], causal=\u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.causal)","        \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.transformer(tokens, mask=mask), objects.shape[\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e]","","    \u003cspan class=\"tok-comment\"\u003e# forward_with_{robot_path,feasibility,affordance} live in stageb_aux_heads.py (mixin)\u003c/span\u003e","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003e_self_check\u003c/span\u003e():","    \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e torch","","    \u003cspan class=\"tok-keyword\"\u003efrom\u003c/span\u003e clear.data.capability \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e FEATURE_DIM","    \u003cspan class=\"tok-keyword\"\u003efrom\u003c/span\u003e clear.model.encoders \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e obj_feat_dim","","    torch.manual_seed(\u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e)","    b, n, dim = \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e4\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e32\u003c/span\u003e","    grid = torch.zeros(b, \u003cspan class=\"tok-number\"\u003e5\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e8\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e8\u003c/span\u003e)","    object_features = torch.randn(b, n, obj_feat_dim(()))","    capability = torch.randn(b, FEATURE_DIM)","    rank = torch.stack([torch.randperm(n) \u003cspan class=\"tok-keyword\"\u003efor\u003c/span\u003e _ \u003cspan class=\"tok-keyword\"\u003ein\u003c/span\u003e range(b)])","    movable = torch.ones(b, n, dtype=torch.bool)","","    \u003cspan class=\"tok-comment\"\u003e# predict_robot_path=False (the default, and what PAMO/MazePAMO\u0026#x27;s existing\u003c/span\u003e","    \u003cspan class=\"tok-comment\"\u003e# 2 call sites unpack) must be byte-for-byte the pre-extension class.\u003c/span\u003e","    plain = CausalVelocityField(grid_hw=(\u003cspan class=\"tok-number\"\u003e8\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e8\u003c/span\u003e), dim=dim, depth=\u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, heads=\u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, dim_head=\u003cspan class=\"tok-number\"\u003e16\u003c/span\u003e)","    \u003cspan class=\"tok-keyword\"\u003eassert\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e hasattr(","        plain, \u003cspan class=\"tok-string\"\u003e\u0026quot;to_robot_velocity\u0026quot;\u003c/span\u003e","    ), \u003cspan class=\"tok-string\"\u003e\u0026quot;default field must not carry robot heads at all\u0026quot;\u003c/span\u003e","    v, e = plain.forward(grid, object_features, capability, rank, movable)","    \u003cspan class=\"tok-keyword\"\u003eassert\u003c/span\u003e v.shape == (b, n, \u003cspan class=\"tok-number\"\u003e3\u003c/span\u003e) \u003cspan class=\"tok-keyword\"\u003eand\u003c/span\u003e e.shape == (b, n, \u003cspan class=\"tok-number\"\u003e3\u003c/span\u003e)","    print(\u003cspan class=\"tok-string\"\u003e\u0026quot;ok predict_robot_path=False: no robot heads, forward() shape unchanged\u0026quot;\u003c/span\u003e)","","    reachable_feats = torch.randn(b, n, obj_feat_dim((), include_reachable=\u003cspan class=\"tok-keyword\"\u003eTrue\u003c/span\u003e))","    with_reachable = CausalVelocityField(","        grid_hw=(\u003cspan class=\"tok-number\"\u003e8\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e8\u003c/span\u003e), dim=dim, depth=\u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, heads=\u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, dim_head=\u003cspan class=\"tok-number\"\u003e16\u003c/span\u003e, include_reachable=\u003cspan class=\"tok-keyword\"\u003eTrue\u003c/span\u003e","    )","    v, e = with_reachable.forward(grid, reachable_feats, capability, rank, movable)","    \u003cspan class=\"tok-keyword\"\u003eassert\u003c/span\u003e v.shape == (b, n, \u003cspan class=\"tok-number\"\u003e3\u003c/span\u003e) \u003cspan class=\"tok-keyword\"\u003eand\u003c/span\u003e e.shape == (b, n, \u003cspan class=\"tok-number\"\u003e3\u003c/span\u003e)","    print(\u003cspan class=\"tok-string\"\u003e\u0026quot;ok include_reachable=True: to_object_tokens sized for the extra column\u0026quot;\u003c/span\u003e)","","    vf = CausalVelocityField(","        grid_hw=(\u003cspan class=\"tok-number\"\u003e8\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e8\u003c/span\u003e), dim=dim, depth=\u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, heads=\u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, dim_head=\u003cspan class=\"tok-number\"\u003e16\u003c/span\u003e, predict_robot_path=\u003cspan class=\"tok-keyword\"\u003eTrue\u003c/span\u003e","    )","    v2, e2, rv, re = vf.forward_with_robot_path(","        grid, object_features, capability, rank, movable","    )","    \u003cspan class=\"tok-keyword\"\u003eassert\u003c/span\u003e rv.shape == (b, n, \u003cspan class=\"tok-number\"\u003e3\u003c/span\u003e) \u003cspan class=\"tok-keyword\"\u003eand\u003c/span\u003e re.shape == (b, n, \u003cspan class=\"tok-number\"\u003e3\u003c/span\u003e)","    \u003cspan class=\"tok-keyword\"\u003eassert\u003c/span\u003e torch.isfinite(rv).all() \u003cspan class=\"tok-keyword\"\u003eand\u003c/span\u003e torch.isfinite(re).all()","    v3, e3 = vf.forward(grid, object_features, capability, rank, movable)","    \u003cspan class=\"tok-keyword\"\u003eassert\u003c/span\u003e torch.allclose(v2, v3) \u003cspan class=\"tok-keyword\"\u003eand\u003c/span\u003e torch.allclose(","        e2, e3","    ), \u003cspan class=\"tok-string\"\u003e\u0026quot;forward() and forward_with_robot_path() must share the identical trunk output\u0026quot;\u003c/span\u003e","    print(","        \u003cspan class=\"tok-string\"\u003e\u0026quot;ok predict_robot_path=True: robot heads present, shared trunk output matches forward()\u0026quot;\u003c/span\u003e","    )","","    (rv.sum() + re.sum()).backward()","    print(\u003cspan class=\"tok-string\"\u003e\u0026quot;ok gradients reach the robot-path heads\u0026quot;\u003c/span\u003e)","","    \u003cspan class=\"tok-comment\"\u003e# condition_smoothness=False (default) must stay byte-for-byte identical too,\u003c/span\u003e","    \u003cspan class=\"tok-comment\"\u003e# and =True must actually change the output when the scalar changes.\u003c/span\u003e","    \u003cspan class=\"tok-keyword\"\u003eassert\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e hasattr(","        plain, \u003cspan class=\"tok-string\"\u003e\u0026quot;smoothness_to_bias\u0026quot;\u003c/span\u003e","    ), \u003cspan class=\"tok-string\"\u003e\u0026quot;default field must not carry the smoothness bias at all\u0026quot;\u003c/span\u003e","    sv = CausalVelocityField(","        grid_hw=(\u003cspan class=\"tok-number\"\u003e8\u003c/span\u003e, \u003cspan class=\"tok-number\"\u003e8\u003c/span\u003e),","        dim=dim,","        depth=\u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e,","        heads=\u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e,","        dim_head=\u003cspan class=\"tok-number\"\u003e16\u003c/span\u003e,","        condition_smoothness=\u003cspan class=\"tok-keyword\"\u003eTrue\u003c/span\u003e,","    )","    lo = torch.zeros(b)","    hi = torch.ones(b)","    v_lo, _ = sv.forward(","        grid, object_features, capability, rank, movable, smoothness_cond=lo","    )","    v_hi, _ = sv.forward(","        grid, object_features, capability, rank, movable, smoothness_cond=hi","    )","    \u003cspan class=\"tok-keyword\"\u003eassert\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e torch.allclose(","        v_lo, v_hi","    ), \u003cspan class=\"tok-string\"\u003e\u0026quot;smoothness_cond=0 vs 1 produced identical output\u0026quot;\u003c/span\u003e","    \u003cspan class=\"tok-keyword\"\u003etry\u003c/span\u003e:","        sv.forward(grid, object_features, capability, rank, movable)","        \u003cspan class=\"tok-keyword\"\u003eraise\u003c/span\u003e AssertionError(","            \u003cspan class=\"tok-string\"\u003e\u0026quot;condition_smoothness=True must require smoothness_cond, not silently default it\u0026quot;\u003c/span\u003e","        )","    \u003cspan class=\"tok-keyword\"\u003eexcept\u003c/span\u003e AssertionError \u003cspan class=\"tok-keyword\"\u003eas\u003c/span\u003e e:","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e \u003cspan class=\"tok-string\"\u003e\u0026quot;requires smoothness_cond\u0026quot;\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003ein\u003c/span\u003e str(e):","            \u003cspan class=\"tok-keyword\"\u003eraise\u003c/span\u003e","    print(","        \u003cspan class=\"tok-string\"\u003e\u0026quot;ok condition_smoothness=True: output actually depends on the scalar, and is required\u0026quot;\u003c/span\u003e","    )","","","\u003cspan class=\"tok-comment\"\u003e# ---- target_flow ----\u003c/span\u003e","\u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e math","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003eselection_mask\u003c/span\u003e(logits, available):","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e available \u0026amp; (logits \u0026gt; \u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e)","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003epriority_scale\u003c/span\u003e(raw, minimum=\u003cspan class=\"tok-number\"\u003e0.05\u003c/span\u003e, maximum=\u003cspan class=\"tok-number\"\u003e0.5\u003c/span\u003e):","    \u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;Smooth bounded Gaussian scale; no hard-clamp dead zone.\u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e minimum + (maximum - minimum) * torch.sigmoid(raw)","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003eselected_ranks\u003c/span\u003e(rank, available):","    n = rank.shape[-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e]","    selected = available \u0026amp; (rank \u0026gt;= \u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e) \u0026amp; (rank \u0026lt; n)","    \u003cspan class=\"tok-comment\"\u003e# zeros_like+n rather than full_like(rank, n): identical result, but the NPU\u003c/span\u003e","    \u003cspan class=\"tok-comment\"\u003e# compiler\u0026#x27;s tvm frontend mishandles full_like with a scalar fill.\u003c/span\u003e","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e torch.where(selected, rank, torch.zeros_like(rank) + n), selected","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003erank_selected\u003c/span\u003e(priority, selected, limit=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e):","    \u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;Ascending sampled priorities; omitted objects use the N sentinel.\u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","    n = priority.shape[-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e]","    \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e limit \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eand\u003c/span\u003e limit \u0026lt; \u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e:","        \u003cspan class=\"tok-keyword\"\u003eraise\u003c/span\u003e ValueError(\u003cspan class=\"tok-string\"\u003e\u0026quot;interaction limit must be nonnegative\u0026quot;\u003c/span\u003e)","    order = priority.masked_fill(~selected, float(\u003cspan class=\"tok-string\"\u003e\u0026quot;inf\u0026quot;\u003c/span\u003e)).argsort(dim=-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e, stable=\u003cspan class=\"tok-keyword\"\u003eTrue\u003c/span\u003e)","    rank = torch.empty_like(order).scatter_(","        \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e, order, torch.arange(n, device=order.device).expand_as(order)","    )","    active = selected \u0026amp; (rank \u0026lt; (n \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e limit \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eelse\u003c/span\u003e limit))","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e torch.where(active, rank, torch.full_like(rank, n)), active","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003etime_embedding\u003c/span\u003e(t, dim):","    half = dim // \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e","    freqs = torch.exp(","        -math.log(\u003cspan class=\"tok-number\"\u003e1000.0\u003c/span\u003e)","        * torch.arange(half, device=t.device, dtype=t.dtype)","        / max(\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e, half - \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e)","    )","    a = t[..., \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e] * freqs","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e torch.cat([a.sin(), a.cos()], dim=-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e)","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003etarget_velocity\u003c/span\u003e(","    static,","    context,","    scene,","    g_t,","    t,","    rank,","    available,","    cfg_in,","    trunk,","    head,","    time_dim,","    causal=\u003cspan class=\"tok-keyword\"\u003eTrue\u003c/span\u003e,","    key_mask=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e,","    causal_bias_slope=\u003cspan class=\"tok-number\"\u003e0.0\u003c/span\u003e,","):","    \u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;Shared Stage B implementation; modules remain owned by each checkpoint.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    `key_mask` (b, 1 + n + s + n) bool marks keys that exist: padded object or\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    scene slots are never read. None keeps the fixed-size behaviour unchanged.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    `causal_bias_slope`: soft-causal ablation (see causal_velocity_field.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    causal_bias). Only meaningful with causal=False -- it grades the\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    movable-to-movable penalty instead of leaving it at zero. 0.0 (default)\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    is a no-op, byte-for-byte the pre-existing behaviour.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    \u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","    rank, selected = selected_ranks(rank, available)","    g_t = torch.where(selected[..., \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e], g_t, torch.zeros_like(g_t))","    b, n, _ = static.shape","    te = time_embedding(t, time_dim)[:, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e].expand(b, n, time_dim)","    obj = cfg_in(torch.cat([static, g_t, te], dim=-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e))","    \u003cspan class=\"tok-comment\"\u003e# A rank restriction applies to generated decisions, never to currently\u003c/span\u003e","    \u003cspan class=\"tok-comment\"\u003e# observed geometry. Separate read-only copies expose ALL observed objects,\u003c/span\u003e","    \u003cspan class=\"tok-comment\"\u003e# including selected objects whose generated targets must remain hidden.\u003c/span\u003e","    observed = cfg_in(torch.cat([static, torch.zeros_like(g_t), te], dim=-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e))","    tokens = torch.cat([context, obj, scene, observed], dim=\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e)","    mask = causal_mask(rank, selected, scene.shape[\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e] + n, causal=causal)","    bias = (","        causal_bias(rank, selected, scene.shape[\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e] + n, causal_bias_slope)","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e causal_bias_slope","        \u003cspan class=\"tok-keyword\"\u003eelse\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e","    )","    \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e key_mask \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e:","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e key_mask.shape != mask.shape[:\u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e]:","            \u003cspan class=\"tok-keyword\"\u003eraise\u003c/span\u003e ValueError(","                \u003cspan class=\"tok-string\"\u003e\u0026quot;key_mask must cover context, objects, scene and observed copies\u0026quot;\u003c/span\u003e","            )","        mask = mask | ~key_mask[:, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e, :]","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e head(trunk(tokens, mask=mask, bias=bias)[:, \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e : \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e + n])","","","\u003cspan class=\"tok-keyword\"\u003eclass\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003eRankCausalTargetFlow\u003c/span\u003e(nn.Module):","    \u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003e__init__\u003c/span\u003e(","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e,","        dim,","        target_dim,","        depth=\u003cspan class=\"tok-number\"\u003e4\u003c/span\u003e,","        heads=\u003cspan class=\"tok-number\"\u003e4\u003c/span\u003e,","        dim_head=\u003cspan class=\"tok-number\"\u003e32\u003c/span\u003e,","        causal=\u003cspan class=\"tok-keyword\"\u003eTrue\u003c/span\u003e,","        causal_bias_slope=\u003cspan class=\"tok-number\"\u003e0.0\u003c/span\u003e,","    ):","        super().__init__()","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e dim % \u003cspan class=\"tok-number\"\u003e4\u003c/span\u003e:","            \u003cspan class=\"tok-keyword\"\u003eraise\u003c/span\u003e ValueError(\u003cspan class=\"tok-string\"\u003e\u0026quot;target flow dim must be divisible by 4\u0026quot;\u003c/span\u003e)","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.dim, \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.target_dim, \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.causal = dim, target_dim, causal","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.noise_std = \u003cspan class=\"tok-number\"\u003e1.0\u003c/span\u003e","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.causal_bias_slope = float(","            causal_bias_slope","        )  \u003cspan class=\"tok-comment\"\u003e# soft-causal ablation, see causal_velocity_field.causal_bias\u003c/span\u003e","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.cfg_in = nn.Sequential(","            nn.Linear(dim + target_dim + dim // \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, dim), nn.GELU(), nn.Linear(dim, dim)","        )","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.trunk = AffordanceTransformer(","            dim, depth=depth, heads=heads, dim_head=dim_head","        )","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.head = nn.Sequential(","            nn.LayerNorm(dim),","            nn.Linear(dim, dim),","            nn.GELU(),","            nn.Linear(dim, target_dim),","        )","","    \u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003eforward\u003c/span\u003e(\u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e, static, context, scene, g_t, t, rank, selected, key_mask=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e):","        \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e target_velocity(","            static,","            context,","            scene,","            g_t,","            t,","            rank,","            selected,","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.cfg_in,","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.trunk,","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.head,","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.dim // \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e,","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.causal,","            key_mask=key_mask,","            causal_bias_slope=\u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.causal_bias_slope,","        )","","    @torch.no_grad()","    \u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003esample\u003c/span\u003e(","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e,","        static,","        context,","        scene,","        rank,","        selected,","        n_steps=\u003cspan class=\"tok-number\"\u003e30\u003c/span\u003e,","        generator=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e,","        key_mask=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e,","        trace=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e,","    ):","        \u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;`trace`, if a list, receives (t, state) at every Euler step and at t=1.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        The states are the generator\u0026#x27;s own intermediates. They exist so a figure\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        can show the flow evolving instead of an interpolation of its endpoint;\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        nothing in the planner reads them and the default path is unchanged.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        \u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e n_steps \u0026lt;= \u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e:","            \u003cspan class=\"tok-keyword\"\u003eraise\u003c/span\u003e ValueError(\u003cspan class=\"tok-string\"\u003e\u0026quot;n_steps must be positive\u0026quot;\u003c/span\u003e)","        rank, selected = selected_ranks(rank, selected)","        g = (","            torch.randn(","                *static.shape[:\u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e],","                \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.target_dim,","                device=static.device,","                dtype=static.dtype,","                generator=generator","            )","            * \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.noise_std","        )","        g = torch.where(selected[..., \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e], g, torch.zeros_like(g))","        \u003cspan class=\"tok-keyword\"\u003efor\u003c/span\u003e k \u003cspan class=\"tok-keyword\"\u003ein\u003c/span\u003e range(n_steps):","            t = torch.full(","                (static.shape[\u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e],),","                k / n_steps,","                device=static.device,","                dtype=static.dtype,","            )","            \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e trace \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e:","                trace.append((k / n_steps, g.detach().clone()))","            v = \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e(static, context, scene, g, t, rank, selected, key_mask=key_mask)","            g = g + torch.where(selected[..., \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e], v, torch.zeros_like(v)) / n_steps","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e trace \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e:","            trace.append((\u003cspan class=\"tok-number\"\u003e1.0\u003c/span\u003e, g.detach().clone()))","        \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e g"],"symbols":[{"name":"causal_mask","start":43,"end":76},{"name":"causal_bias","start":79,"end":98},{"name":"CausalVelocityField","start":104,"end":367},{"name":"CausalVelocityField.__init__","start":105,"end":292},{"name":"CausalVelocityField.forward","start":294,"end":319},{"name":"CausalVelocityField._trunk_out","start":321,"end":334},{"name":"CausalVelocityField._trunk_full","start":336,"end":367},{"name":"_self_check","start":372,"end":457},{"name":"selection_mask","start":464,"end":465},{"name":"priority_scale","start":468,"end":470},{"name":"selected_ranks","start":473,"end":478},{"name":"rank_selected","start":481,"end":491},{"name":"time_embedding","start":494,"end":502},{"name":"target_velocity","start":505,"end":553},{"name":"RankCausalTargetFlow","start":556,"end":652},{"name":"RankCausalTargetFlow.__init__","start":557,"end":586},{"name":"RankCausalTargetFlow.forward","start":588,"end":604},{"name":"RankCausalTargetFlow.sample","start":606,"end":652}]}});
